function deleteApplicationAt(idx) {
  const app = applications[idx];
  if (!app) return;
  if (confirm(`Remove ${app.company} – ${app.role} from the tracker?`)) {
    applications.splice(idx, 1);
    syncTrackerData();
    renderKanban();
    showToast('Application removed');
  }
}

function exportTrackerCSV() {
  const headers = ['date', 'company', 'sector', 'role', 'role_type', 'channel', 'status', 'fit_rating', 'notes', 'source'];
  let csvContent = 'data:text/csv;charset=utf-8,' + headers.join(',') + '\n';

  applications.forEach(a => {
    const row = headers.map(h => {
      let val = a[h] || '';
      if (typeof val === 'string' && (val.includes(',') || val.includes('"'))) {
        val = `"${val.replace(/"/g, '""')}"`;
      }
      return val;
    });
    csvContent += row.join(',') + '\n';
  });

  const encodedUri = encodeURI(csvContent);
  const link = document.createElement('a');
  link.setAttribute('href', encodedUri);
  link.setAttribute('download', `job_search_tracker_${new Date().toISOString().split('T')[0]}.csv`);
  document.body.appendChild(link);
  link.click();
  document.body.removeChild(link);
}

// Utility Helpers
function escapeHtml(str) {
  if (!str) return '';
  return String(str)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#039;');
}

function initials(name) {
  return String(name || '?').split(/\s+/).filter(Boolean).slice(0, 2).map(w => w[0]).join('').toUpperCase();
}

function formatDate(date) {
  if (!date) return 'Recent';
  const d = new Date(date);
  if (isNaN(d)) return date;
  return d.toLocaleDateString(undefined, { month: 'short', day: 'numeric' });
}

function fitColor(fit) {
  return fit >= 80 ? 'var(--ok)' : fit >= 60 ? 'var(--warn)' : 'var(--st-closed)';
}

function statusPill(status) {
  const s = STATUS[status] || { label: status || 'Unknown', color: 'var(--text-3)' };
  return `<span class="status" style="--c: ${s.color}">${escapeHtml(s.label)}</span>`;
}

let toastTimer;
function showToast(message, duration = 2200) {
  const toast = document.getElementById('toast');
  toast.textContent = message;
  toast.classList.add('show');
  clearTimeout(toastTimer);
  toastTimer = setTimeout(() => toast.classList.remove('show'), duration);
}

function copyText(elemId) {
  const elem = document.getElementById(elemId);
  if (!elem) return;
  navigator.clipboard.writeText(elem.innerText || elem.textContent)
    .then(() => showToast('Copied to clipboard'))
    .catch(() => showToast('Copy failed'));
}


// Tailor CV tab - builds a job-specific CV from the profile via /api/tailor.
// Kept separate from app.js; relies only on its shared helpers
// (switchTab, showToast, escapeHtml, PAGES).

PAGES.tailor = ['Tailor CV', 'Reshape your CV around a specific job description.'];

let tailorResult = null;

// Which CV is tailored: the selected profile, or "another CV" uploaded or pasted here
// (read in the browser, sent with each request, never saved to a profile)
let tailorSource = { kind: 'profile', name: '', markdown: '', label: '' };

function tailorOneOffMarkdown() {
  return tailorSource.kind === 'other' ? tailorSource.markdown : '';
}

function setTailorSource(kind) {
  if (kind === tailorSource.kind) return;
  if (tailorWs.edited && !confirm('Switching CVs clears the tailored CV and your edits. Continue?')) return;
  tailorSource.kind = kind;
  document.querySelectorAll('.cv-source .seg-btn').forEach(b => {
    const on = b.dataset.src === kind;
    b.classList.toggle('on', on);
    b.setAttribute('aria-checked', on);
  });
  document.getElementById('cv-source-other').hidden = kind !== 'other';
  // A different CV: start the tailoring over
  tailorConfirmed.clear();
  tailorJobKey = '';
  resetTailor();
}

async function handleTailorCvFile(input) {
  const file = input.files && input.files[0];
  input.value = '';
  if (!file) return;
  if (file.size > CV_MAX_BYTES) return showToast('That file is larger than 10 MB');
  showToast(`Reading ${file.name}…`, 60000);
  try {
    useTailorCv(await readCv(file), file.name);
  } catch (err) {
    console.warn('CV read failed', err);
    showToast(friendlyCvError(err), 8000);
  }
}

function useTailorCvText() {
  const text = document.getElementById('tailor-cv-text').value;
  if (text.replace(/\s/g, '').length < 80) return showToast('Paste the whole CV (it looks too short)');
  try {
    useTailorCv(parseCvText(text), 'pasted text');
  } catch (err) {
    showToast('Could not read that text as a CV');
  }
}

function useTailorCv(cv, from) {
  if (!cv.name || !cv.experience.length) {
    showToast('Could not find a name and work experience in that CV. Try the other format (file or pasted text).', 7000);
    return;
  }
  tailorSource = { kind: 'other', name: cv.name, markdown: buildProfileMarkdown(cv, null), label: from };
  const skills = cv.skills.reduce((n, g) => n + g.items.length, 0);
  document.getElementById('tailor-cv-status').innerHTML =
    `Using <strong>${escapeHtml(cv.name)}</strong>'s CV (from ${escapeHtml(from)}): ${cv.experience.length} role${cv.experience.length === 1 ? '' : 's'}, ${skills} skill${skills === 1 ? '' : 's'}${cv.projects.length ? `, ${cv.projects.length} project${cv.projects.length === 1 ? '' : 's'}` : ''}. Not saved to any profile.`;
  tailorConfirmed.clear();
  tailorJobKey = '';
  resetTailor();
  showToast(`${cv.name}'s CV is ready. Add the job and click Tailor my CV.`, 4000);
}

// Skills the candidate confirmed for the current job (gaps their profile doesn't mention)
const tailorConfirmed = new Set();
let tailorJobKey = '';

// The CV layout's own styles come with the result, so the preview matches the LaTeX
// CV layout chosen in the toolbar (remembered on this device)
let tailorLayout = 'ats-classic';
try { tailorLayout = localStorage.getItem('cvLayout') || tailorLayout; } catch (e) {}

// The tailored CV in the chosen layout (every layout comes with each result)
function currentLayout() {
  const r = tailorResult;
  return (r.layouts && (r.layouts[tailorLayout] || r.layouts[r.template])) || { html: r.html, css: r.css, latex: r.latex };
}

function setTailorLayout(id) {
  tailorLayout = id;
  try { localStorage.setItem('cvLayout', id); } catch (e) {}
  // The style toolbar shows this layout's own choices
  tailorWs.layout = id;
  tailorWs.menu = null;
  renderStyleBar(tailorWs);
  renderTailorPreview();
}

function renderLayoutPicker() {
  const select = document.getElementById('tailor-layout');
  const layouts = tailorResult.layouts || {};
  if (!layouts[tailorLayout]) tailorLayout = tailorResult.template || Object.keys(layouts)[0] || tailorLayout;
  select.innerHTML = Object.entries(layouts).map(([id, l]) => `<option value="${escapeHtml(id)}"${id === tailorLayout ? ' selected' : ''}>${escapeHtml(l.label)}</option>`).join('');
  select.hidden = Object.keys(layouts).length < 2;
}

// A CV as a standalone page for the preview frame and printing (css: the layout's styles)
function cvDocument(html, title, highlight, css) {
  return `<!doctype html><html><head><meta charset="utf-8"><title>${escapeHtml(title)}</title>
<style>${css != null ? css : currentLayout().css}</style></head><body class="${highlight ? 'highlight' : ''}"><div class="page">${html}</div></body></html>`;
}

function importFromEvaluator() {
  const title = document.getElementById('eval-job-title').value;
  const company = document.getElementById('eval-company-name').value;
  const desc = document.getElementById('eval-job-desc').value;
  if (!desc.trim()) {
    showToast('The Evaluate tab has no job description yet');
    return;
  }
  document.getElementById('tailor-title').value = title;
  document.getElementById('tailor-company').value = company;
  document.getElementById('tailor-desc').value = desc;
  showToast('Job imported from Evaluate');
}

// "Tailor CV for this job" on the Evaluate tab: fill in the job and build the CV
function tailorJob(title, company, description) {
  if (!String(description || '').trim()) {
    showToast('Add the job description first');
    return;
  }
  document.getElementById('tailor-title').value = title || '';
  document.getElementById('tailor-company').value = company || '';
  document.getElementById('tailor-desc').value = description;
  switchTab('tailor');
  runTailor();
}

function tailorFromEvaluator() {
  tailorJob(
    document.getElementById('eval-job-title').value,
    document.getElementById('eval-company-name').value,
    document.getElementById('eval-job-desc').value
  );
}

// Confirm or remove a skill the profile doesn't mention. The score and skills update
// straight away; Claude's wording is refreshed with "Rewrite with Claude" when ready.
function toggleConfirmedSkill(name) {
  if (tailorConfirmed.has(name)) tailorConfirmed.delete(name);
  else tailorConfirmed.add(name);
  runTailor({ ai: false });
}

// ai: false skips Claude's rewrite (quick update after confirming a skill)
async function runTailor({ ai = true } = {}) {
  const title = document.getElementById('tailor-title').value.trim();
  const company = document.getElementById('tailor-company').value.trim();
  const description = document.getElementById('tailor-desc').value.trim();
  const button = document.getElementById('tailor-run');

  // Confirmed skills belong to one job; start fresh when the job changes
  const key = `${title}\n${company}\n${description}`;
  if (key !== tailorJobKey) {
    tailorConfirmed.clear();
    tailorJobKey = key;
  }

  if (!description) {
    showToast('Paste the job description first');
    document.getElementById('tailor-desc').focus();
    return;
  }
  if (tailorSource.kind === 'other' && !tailorSource.markdown) {
    showToast('Upload or paste the CV to tailor first');
    return;
  }
  // Tailoring again rebuilds the CV from the profile
  if (tailorWs.edited && !confirm('Tailoring again replaces the edits you made in Edit CV. Continue?')) return;

  button.disabled = true;
  button.textContent = ai ? 'Tailoring… (this can take up to a minute)' : 'Updating…';
  try {
    const res = await fetch(apiUrl('/api/tailor'), {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ title, company, description, confirmedSkills: [...tailorConfirmed], ai, template: tailorLayout, styles: tailorWs.styles, profileMarkdown: tailorOneOffMarkdown() || undefined })
    });
    const data = await res.json();
    if (!res.ok) throw new Error(data.error || 'Tailoring failed');
    tailorResult = data;
    renderTailorResult();
  } catch (err) {
    showToast(err.message || 'Could not reach the server');
  } finally {
    button.disabled = false;
    button.textContent = 'Tailor my CV';
  }
}

// The ring is the CV match: how much of what you meet the tailored CV shows (100% once
// tailored). Job fit (required skills you have at all) is shown underneath. Also called
// after each edit in Edit CV, since editing can remove a skill from the CV.
function renderTailorScore() {
  const r = tailorResult;
  const { analysis } = r;
  const req = analysis.matched.filter(m => m.required).length;
  const reqTotal = req + analysis.missing.filter(m => m.required).length;
  const cov = r.coverage || { cvScore: analysis.matchScore, cvShown: req, cvNeeded: req, notShown: [] };
  const ring = document.getElementById('tailor-score');
  ring.style.setProperty('--score', cov.cvScore);
  ring.classList.remove('good', 'fair', 'low');
  ring.classList.add(cov.cvScore >= 75 ? 'good' : cov.cvScore >= 50 ? 'fair' : 'low');
  document.getElementById('tailor-score-num').textContent = `${cov.cvScore}%`;
  const gaps = reqTotal - req;
  document.getElementById('tailor-score-text').innerHTML = !reqTotal
    ? 'No specific required skills were detected in this posting.'
    : (cov.cvScore === 100
      ? `This CV shows <strong>all ${cov.cvShown}</strong> of the posting's required skills that you meet.`
      : `This CV shows <strong>${cov.cvShown} of ${cov.cvNeeded}</strong> required skills you meet (missing: ${escapeHtml(cov.notShown.join(', '))}).`)
      + `<span class="tailor-fit">Job fit: you meet <strong>${req} of ${reqTotal}</strong> required skills (${analysis.matchScore}%)${gaps
        ? `. ${gaps === 1 ? 'One is' : `${gaps} are`} not in your profile: click <strong>+ I have this</strong> below if you have ${gaps === 1 ? 'it' : 'them'}.`
        : '.'}</span>`;
}

// The recruiter review: a recruiter's first read (score, missing keywords, red flags),
// the XYZ check of every bullet and the ATS / hiring-manager skim. Also called after
// each edit in Edit CV.
function renderTailorReview() {
  const card = document.getElementById('tailor-review');
  const rv = tailorResult && tailorResult.review;
  card.hidden = !rv;
  if (!rv) return;
  const band = (n, good, fair) => (n >= good ? 'good' : n >= fair ? 'fair' : 'low');
  const setBadge = (id, text, kind) => {
    const el = document.getElementById(id);
    el.textContent = text;
    el.className = `review-badge ${kind}`;
  };

  const { recruiter, xyz, skim } = rv;
  setBadge('review-score', `${recruiter.score}/100`, band(recruiter.score, 80, 60));
  document.getElementById('review-recruiter').innerHTML = `
    <ul class="review-parts">${recruiter.parts.map(p => `<li><span>${escapeHtml(p.label)} <small>(${escapeHtml(p.note)})</small></span><strong>${p.of ? `${p.points}/${p.of}` : p.points}</strong></li>`).join('')}</ul>
    <h3 class="review-sub">Most important missing keywords</h3>
    ${recruiter.missingKeywords.length
      ? `<div class="req-chips">${recruiter.missingKeywords.map(k => `<span class="req-chip gap">${escapeHtml(k.name)}${k.required ? '' : '<small>nice to have</small>'}</span>`).join('')}</div>`
      : '<p class="review-ok">None: the CV covers every keyword this posting names.</p>'}
    <h3 class="review-sub">Biggest red flags in the first 10 seconds</h3>
    ${recruiter.redFlags.length
      ? `<ul class="review-flags">${recruiter.redFlags.map(f => `<li><strong>${escapeHtml(f.title)}.</strong> ${escapeHtml(f.detail)}<span class="review-fix">${escapeHtml(f.fix)}</span></li>`).join('')}</ul>${recruiter.moreFlags ? `<p class="review-ok">${recruiter.moreFlags} smaller issue${recruiter.moreFlags > 1 ? 's' : ''} not shown.</p>` : ''}`
      : '<p class="review-ok">No red flags a recruiter would spot in 10 seconds.</p>'}`;

  setBadge('review-xyz-badge', `${xyz.full}/${xyz.total} full XYZ`, band(xyz.total ? xyz.full / xyz.total : 0, 0.7, 0.4));
  const tags = (list) => `<span class="review-tags">${list.map(x => `<span>no ${escapeHtml(x)}</span>`).join('')}</span>`;
  document.getElementById('review-xyz').innerHTML = `
    <p class="review-ok">Accomplished <strong>X</strong>, as measured by <strong>Y</strong>, by doing <strong>Z</strong>. ${xyz.quantified} of ${xyz.total} bullets have a measured result.</p>
    ${xyz.rewrites.length ? `<h3 class="review-sub">Rewritten for you</h3><ul class="review-list">${xyz.rewrites.map(w => `<li><span class="review-before">${escapeHtml(w.before)}</span><span class="review-after">${escapeHtml(w.after)}</span></li>`).join('')}</ul>` : ''}
    ${xyz.needNumbers.length
      ? `<h3 class="review-sub">Add a number to these</h3><ul class="review-list">${xyz.needNumbers.map(b => `<li><strong>${escapeHtml(b.where)}</strong>${tags(b.missing)}<br>${escapeHtml(b.text)}</li>`).join('')}</ul>
         <p class="review-ok">Only add numbers you can back up: % faster or cheaper, time saved, users or requests served, revenue, team size. Edit them in <strong>Edit CV</strong>.</p>`
      : '<p class="review-ok">Every bullet has a measured result.</p>'}`;

  const counts = skim.sections.reduce((c, s) => ({ ...c, [s.verdict]: (c[s.verdict] || 0) + 1 }), {});
  const worst = counts.reject ? 'low' : counts.skip ? 'fair' : 'good';
  setBadge('review-skim-badge', counts.reject ? `${counts.reject} reject` : `${counts.read || 0} read · ${counts.skim || 0} skim${counts.skip ? ` · ${counts.skip} skip` : ''}`, worst);
  document.getElementById('review-skim').innerHTML = `
    <p class="review-ok">About ${skim.pages} page${skim.pages > 1 ? 's' : ''}. What a reviewer with 200 CVs reads, skims, skips or rejects:</p>
    <ul class="review-list review-skim">${skim.sections.map(s => `<li><span class="verdict ${s.verdict}">${escapeHtml(s.verdict)}</span><span><strong>${escapeHtml(s.section)}</strong>: ${escapeHtml(s.reason)}${s.fix ? `<span class="review-fix">${escapeHtml(s.fix)}</span>` : ''}</span></li>`).join('')}</ul>`;
}

// The "Covered in your CV" and "Not in your profile" chips
function renderTailorChips() {
  const { analysis } = tailorResult;
  // Why a skill counts (or doesn't count) toward the score
  const tag = (m) => m.implied ? `via ${m.implied}`
    : m.soft ? 'soft skill'
    : m.note === 'alternative' ? 'alternative'
    : m.note === 'example' ? 'example'
    : m.required ? '' : 'nice to have';
  const label = (m) => `${escapeHtml(m.name)}${tag(m) ? `<small>${escapeHtml(tag(m))}</small>` : ''}`;
  const arg = (m) => escapeHtml(JSON.stringify(m.name));
  document.getElementById('tailor-matched').innerHTML = analysis.matched.length
    ? analysis.matched.map(m => m.confirmed
      ? `<button class="req-chip hit confirmed" onclick="toggleConfirmedSkill(${arg(m)})" title="You confirmed this skill. Click to remove it from the CV.">${label(m)}<span class="chip-x" aria-hidden="true">×</span></button>`
      : `<span class="req-chip hit"${m.implied ? ` title="Your profile shows this through ${escapeHtml(m.implied)}"` : ''}>${label(m)}</span>`).join('')
    : '<span class="muted">None detected</span>';
  document.getElementById('tailor-missing').innerHTML = analysis.missing.length
    ? analysis.missing.map(m => `<button class="req-chip gap" onclick="toggleConfirmedSkill(${arg(m)})" title="Add this skill to your CV if you really have it">${label(m)}<span class="chip-add">+ I have this</span></button>`).join('')
    : '<span class="muted">No gaps - you cover everything we detected.</span>';
  document.getElementById('tailor-gap-block').hidden = false;
}

function renderTailorResult() {
  const r = tailorResult;
  renderTailorScore();
  renderTailorReview();
  renderTailorChips();

  document.getElementById('tailor-changes').innerHTML = r.changes.map(c => `<li>${escapeHtml(c)}</li>`).join('');
  renderTailorAiNote(r.ai || {});

  document.getElementById('tailor-analysis').hidden = false;
  document.getElementById('tailor-empty').hidden = true;
  document.getElementById('tailor-preview').hidden = false;
  document.getElementById('tailor-file').textContent = r.filename;
  renderLayoutPicker();
  // The tailored CV is now what Edit CV and the style toolbar work on
  cveLoadTailored(r);
  renderTailorPreview();
}

// Says whether AI rewrote this CV; stays quiet (no banner) when it didn't, rather than
// surfacing an internal error (token budget, rate limit, provider name) to the user
function renderTailorAiNote(ai) {
  const note = document.getElementById('tailor-ai-note');
  if (ai.used) {
    note.className = 'tailor-ai-note ok';
    note.innerHTML = '<strong>Rewritten by AI</strong> for this job, using only facts from your profile and skills you confirmed.';
    note.hidden = false;
    return;
  }
  note.hidden = true;
}

function renderTailorPreview() {
  if (!tailorResult) return;
  const frame = document.getElementById('tailor-frame');
  const highlight = document.getElementById('tailor-highlight').checked;
  frame.srcdoc = cvDocument(currentLayout().html, cvTitle(), highlight);
  frame.onload = () => {
    frame.style.height = `${frame.contentDocument.documentElement.scrollHeight}px`;
  };
}

function cvTitle() {
  const { title, company } = tailorResult.job;
  return `${tailorResult.cv.name} - CV${company ? ` - ${company}` : ''}${title ? ` - ${title}` : ''}`;
}

// Real PDF compiled from the chosen LaTeX layout (with your edits and styling)
function downloadTailoredPdf(button) {
  if (!tailorResult) return;
  cveDownloadPdf(tailorWs, button, printTailoredPdf);
}

// Fallback: print the preview ("Save as PDF" in the print dialog)
function printTailoredPdf() {
  if (!tailorResult) return;
  const frame = document.createElement('iframe');
  frame.style.cssText = 'position:fixed;right:0;bottom:0;width:0;height:0;border:0;';
  document.body.appendChild(frame);
  frame.srcdoc = cvDocument(currentLayout().html, cvTitle(), false);
  frame.onload = () => {
    // Let the web font settle before printing
    setTimeout(() => {
      frame.contentWindow.focus();
      frame.contentWindow.print();
      setTimeout(() => frame.remove(), 1000);
    }, 400);
  };
  showToast('Choose "Save as PDF" in the print dialog');
}

function downloadTailoredTex() {
  if (!tailorResult) return;
  const blob = new Blob([currentLayout().latex], { type: 'application/x-tex' });
  const link = document.createElement('a');
  link.href = URL.createObjectURL(blob);
  link.download = tailorResult.filename;
  document.body.appendChild(link);
  link.click();
  link.remove();
  setTimeout(() => URL.revokeObjectURL(link.href), 1000);
}

async function saveTailoredToProject() {
  if (!tailorResult) return;
  const { title, company } = tailorResult.job;
  try {
    const res = await fetch(apiUrl('/api/tailor'), {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      // The exact CV on screen (latex + filename); title/description for the local dashboard server
      body: JSON.stringify({ title, company, description: document.getElementById('tailor-desc').value, confirmedSkills: [...tailorConfirmed], save: true, latex: currentLayout().latex, filename: tailorResult.filename })
    });
    const data = await res.json();
    if (!res.ok) throw new Error(data.error);
    showToast(`Saved to ${data.savedTo}`);
  } catch (err) {
    showToast(err.message || 'Save failed');
  }
}

function copyTailoredText() {
  if (!tailorResult) return;
  navigator.clipboard.writeText(tailorResult.text)
    .then(() => showToast('CV copied as plain text'))
    .catch(() => showToast('Copy failed'));
}


// CV editing and styling (ported from the CV adjustment kit's InlineEditor, the section
// editors and PreviewToolbar). Used in two places:
//   - Tailor CV: an "Edit CV" panel and a style toolbar for the tailored CV
//   - CV Editor tab: build and style a CV on your own, from the profile or from scratch
// Relies on app.js helpers (escapeHtml, showToast, apiUrl, PAGES, activeProfile).

PAGES['cv-editor'] = ['CV Editor', 'Edit and style your CV yourself, starting from your profile or a blank page.'];

const CVE_FONTS = [['template', 'Template font'], ['helvetica', 'Helvetica'], ['times', 'Times'], ['palatino', 'Palatino'], ['century-gothic', 'Century Gothic']];
const CVE_SIZES = [10, 11, 12];
const CVE_ACCENTS = ['#111111', '#1F4E79', '#0F766E', '#A81450', '#B45309', '#4C1D95', '#166534', '#6B7280'];
const CVE_LINE = [[1, 'Single'], [1.15, '1.15'], [1.3, '1.3'], [1.5, '1.5']];
const CVE_GAP = [[0.7, 'Compact'], [1, 'Normal'], [1.3, 'Relaxed'], [1.6, 'Airy']];
const CVE_SECTION_IDS = ['summary', 'experience', 'education', 'skills', 'projects', 'certifications'];
const CVE_SECTION_LABELS = { summary: 'Summary', experience: 'Experience', education: 'Education', skills: 'Skills', projects: 'Projects', certifications: 'Certifications' };
const CVE_PANELS = [
  ['personal', 'Personal information'], ['summary', 'Professional summary'], ['experience', 'Work experience'],
  ['education', 'Education'], ['skills', 'Skills'], ['projects', 'Projects'], ['certifications', 'Certifications']
];

// ---------- Workspaces ----------

// One CV being edited, with its per-layout style choices and last render
function cveWorkspace(opts) {
  return Object.assign({ cv: null, styles: {}, layout: 'ats-classic', result: null, timer: null, seq: 0, open: 'personal', edited: false, menu: null, aiNotes: {}, aiDrafts: {}, aiUndo: [] }, opts);
}

const tailorWs = cveWorkspace({
  key: 'tailor',
  // "Another CV" on the Tailor page stands in for the profile
  oneOff: () => (typeof tailorOneOffMarkdown === 'function' ? tailorOneOffMarkdown() : ''),
  editorId: 'tailor-editor-body',
  barId: 'tailor-style-bar',
  job: () => ({
    title: document.getElementById('tailor-title').value.trim(),
    company: document.getElementById('tailor-company').value.trim(),
    description: document.getElementById('tailor-desc').value.trim(),
    confirmedSkills: typeof tailorConfirmed !== 'undefined' ? [...tailorConfirmed] : []
  }),
  onRendered(data) {
    if (!tailorResult) return;
    Object.assign(tailorResult, { cv: data.cv, layouts: data.layouts, text: data.text, html: data.html, css: data.css, latex: data.latex });
    if (data.coverage) tailorResult.coverage = data.coverage;
    if (data.review) {
      // Keep the list of wording fixes made when the CV was tailored
      const rewrites = tailorResult.review && tailorResult.review.xyz ? tailorResult.review.xyz.rewrites : [];
      tailorResult.review = { ...data.review, xyz: { ...data.review.xyz, rewrites } };
    }
    if (typeof renderTailorScore === 'function') renderTailorScore();
    if (typeof renderTailorReview === 'function') renderTailorReview();
    if (typeof instructSync === 'function') instructSync();
    renderTailorPreview();
  }
});

const ownWs = cveWorkspace({
  key: 'own',
  editorId: 'own-editor-body',
  barId: 'own-style-bar',
  job: () => ({}),
  onRendered() {
    renderOwnPreview();
    cveSaveDraft(ownWs);
  }
});

function cveLayoutDefaults(ws) {
  const layouts = (ws.result && ws.result.layouts) || {};
  return (layouts[ws.layout] && layouts[ws.layout].defaults) || { fontFamily: 'template', fontSize: 10, headerAlign: 'center', accentColor: '#000000', lineSpacing: 1, sectionSpacing: 1, boldHeadings: true, italicHeadings: false, sections: CVE_SECTION_IDS };
}

function cveStyle(ws) {
  return Object.assign({}, cveLayoutDefaults(ws), ws.styles[ws.layout] || {});
}

// Re-render on the server after a change (debounced; stale answers are ignored)
function cveRender(ws, delay = 500) {
  clearTimeout(ws.timer);
  ws.timer = setTimeout(async () => {
    const seq = ++ws.seq;
    try {
      const res = await fetch(apiUrl('/api/cv/render'), {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ cv: ws.cv, styles: ws.styles, template: ws.layout, job: ws.job(), profileMarkdown: ws.oneOff ? ws.oneOff() || undefined : undefined })
      });
      const data = await res.json();
      if (seq !== ws.seq) return;
      if (!res.ok) throw new Error(data.error || 'Could not update the preview');
      ws.result = data;
      ws.onRendered(data);
    } catch (err) {
      if (seq === ws.seq) showToast(err.message || 'Could not update the preview');
    }
  }, delay);
}

// ---------- Style toolbar ----------

function cveSetStyle(ws, patch) {
  ws.styles[ws.layout] = Object.assign({}, ws.styles[ws.layout] || {}, patch);
  renderStyleBar(ws);
  cveRender(ws, 120);
}

function cveResetStyle(ws) {
  delete ws.styles[ws.layout];
  ws.menu = null;
  renderStyleBar(ws);
  cveRender(ws, 0);
}

function cveToggleMenu(ws, name) {
  ws.menu = ws.menu === name ? null : name;
  renderStyleBar(ws);
}

function cveMoveSection(ws, id, dir) {
  const order = [...cveStyle(ws).sections];
  const from = order.indexOf(id), to = from + dir;
  if (from < 0 || to < 0 || to >= order.length) return;
  [order[from], order[to]] = [order[to], order[from]];
  cveSetStyle(ws, { sections: order });
}

function cveToggleSection(ws, id) {
  const shown = cveStyle(ws).sections;
  if (shown.includes(id)) {
    if (shown.length === 1) return showToast('A CV needs at least one section');
    cveSetStyle(ws, { sections: shown.filter(x => x !== id) });
  } else {
    cveSetStyle(ws, { sections: [...shown, id] });
  }
}

function renderStyleBar(ws) {
  const bar = document.getElementById(ws.barId);
  if (!bar) return;
  if (!ws.result) { bar.hidden = true; return; }
  bar.hidden = false;
  const s = cveStyle(ws);
  const touched = Boolean(ws.styles[ws.layout] && Object.keys(ws.styles[ws.layout]).length);
  const w = `CVE_WS['${ws.key}']`;
  const opt = (value, label, current) => `<option value="${escapeHtml(String(value))}"${String(value) === String(current) ? ' selected' : ''}>${escapeHtml(label)}</option>`;
  const toggle = (on, label, title, action) => `<button type="button" class="sb-btn${on ? ' on' : ''}" aria-pressed="${on}" title="${title}" onclick="${action}">${label}</button>`;
  const hidden = CVE_SECTION_IDS.filter(id => !s.sections.includes(id));

  bar.innerHTML = `
    <button type="button" class="sb-btn" title="Reset to this layout's own styling" onclick="cveResetStyle(${w})" ${touched ? '' : 'disabled'}>↺</button>
    <span class="sb-sep"></span>
    <select class="input sb-select" aria-label="Font" onchange="cveSetStyle(${w}, { fontFamily: this.value })">${CVE_FONTS.map(([v, l]) => opt(v, l, s.fontFamily)).join('')}</select>
    <select class="input sb-select sb-narrow" aria-label="Font size" onchange="cveSetStyle(${w}, { fontSize: Number(this.value) })">${CVE_SIZES.map(v => opt(v, `${v} pt`, s.fontSize)).join('')}</select>
    <span class="sb-sep"></span>
    ${toggle(s.boldHeadings, '<b>B</b>', 'Bold section headings', `cveSetStyle(${w}, { boldHeadings: ${!s.boldHeadings} })`)}
    ${toggle(s.italicHeadings, '<i>I</i>', 'Italic section headings', `cveSetStyle(${w}, { italicHeadings: ${!s.italicHeadings} })`)}
    <span class="sb-sep"></span>
    ${[['left', '⇤', 'Header left'], ['center', '↔', 'Header centred'], ['right', '⇥', 'Header right']].map(([a, icon, t]) => toggle(s.headerAlign === a, icon, t, `cveSetStyle(${w}, { headerAlign: '${a}' })`)).join('')}
    <span class="sb-sep"></span>
    <div class="sb-pop">
      <button type="button" class="sb-btn" title="Accent colour" aria-expanded="${ws.menu === 'colour'}" onclick="cveToggleMenu(${w}, 'colour')"><span class="sb-swatch" style="background:${escapeHtml(s.accentColor)}"></span></button>
      ${ws.menu === 'colour' ? `<div class="sb-menu sb-colours">
        ${CVE_ACCENTS.map(c => `<button type="button" class="sb-colour${c.toLowerCase() === String(s.accentColor).toLowerCase() ? ' on' : ''}" style="background:${c}" title="${c}" aria-label="Accent ${c}" onclick="cveSetStyle(${w}, { accentColor: '${c}' }); CVE_WS['${ws.key}'].menu = null; renderStyleBar(${w})"></button>`).join('')}
        <label class="sb-custom">Custom <input type="color" value="${escapeHtml(s.accentColor)}" onchange="cveSetStyle(${w}, { accentColor: this.value })"></label>
      </div>` : ''}
    </div>
    <select class="input sb-select" aria-label="Line spacing" title="Line spacing" onchange="cveSetStyle(${w}, { lineSpacing: Number(this.value) })">${CVE_LINE.map(([v, l]) => opt(v, `Lines: ${l}`, s.lineSpacing)).join('')}</select>
    <select class="input sb-select" aria-label="Space between sections" title="Space between sections" onchange="cveSetStyle(${w}, { sectionSpacing: Number(this.value) })">${CVE_GAP.map(([v, l]) => opt(v, `Sections: ${l}`, s.sectionSpacing)).join('')}</select>
    <div class="sb-pop sb-right">
      <button type="button" class="sb-btn sb-text" aria-expanded="${ws.menu === 'sections'}" onclick="cveToggleMenu(${w}, 'sections')">Sections ▾</button>
      ${ws.menu === 'sections' ? `<div class="sb-menu sb-sections">
        <p class="sb-menu-label">Shown, in order</p>
        ${s.sections.map((id, i) => `<div class="sb-row">
          <label><input type="checkbox" checked onchange="cveToggleSection(${w}, '${id}')"> ${CVE_SECTION_LABELS[id]}</label>
          <button type="button" aria-label="Move ${CVE_SECTION_LABELS[id]} up" onclick="cveMoveSection(${w}, '${id}', -1)" ${i === 0 ? 'disabled' : ''}>↑</button>
          <button type="button" aria-label="Move ${CVE_SECTION_LABELS[id]} down" onclick="cveMoveSection(${w}, '${id}', 1)" ${i === s.sections.length - 1 ? 'disabled' : ''}>↓</button>
        </div>`).join('')}
        ${hidden.length ? `<p class="sb-menu-label">Hidden</p>${hidden.map(id => `<button type="button" class="sb-add" onclick="cveToggleSection(${w}, '${id}')">+ ${CVE_SECTION_LABELS[id]}</button>`).join('')}` : ''}
      </div>` : ''}
    </div>`;
}

// Close an open style menu when clicking elsewhere
document.addEventListener('mousedown', (e) => {
  for (const ws of Object.values(CVE_WS)) {
    if (ws.menu && !e.target.closest(`#${ws.barId} .sb-pop`)) {
      ws.menu = null;
      renderStyleBar(ws);
    }
  }
});

// ---------- Content editor ----------

const CVE_BLANK = {
  experience: () => ({ role: '', company: '', period: '', location: '', bullets: [''] }),
  education: () => ({ degree: '', school: '', period: '' }),
  skills: () => ({ group: '', items: [] }),
  projects: () => ({ name: '', desc: '', bullets: [''], tech: [] })
};

function cveBlankCV() {
  return { name: '', headline: '', tagline: [], email: '', phone: '', location: '', linkedin: '', github: '', summary: '', skills: [CVE_BLANK.skills()], experience: [CVE_BLANK.experience()], projects: [], education: [CVE_BLANK.education()], certifications: [], languages: [] };
}

// "2021 – Present" -> ['2021', 'Present']
function cvePeriodParts(period) {
  const parts = String(period || '').split(/\s+[–—-]\s+|\s+to\s+|[–—]/i).map(x => x.trim());
  return [parts[0] || '', parts.slice(1).join(' ') || ''];
}

function cveGet(obj, path) {
  return path.split('.').reduce((o, k) => (o == null ? o : o[k]), obj);
}

function cveSet(obj, path, value) {
  const keys = path.split('.');
  const last = keys.pop();
  const target = keys.reduce((o, k) => o[k], obj);
  target[last] = value;
}

// Updates the CV from one form field (no re-render of the form, so typing keeps focus)
function cveField(ws, el) {
  const path = el.dataset.f;
  const kind = el.dataset.t || 'text';
  const v = el.value;
  if (kind === 'lines') cveSet(ws.cv, path, v.split('\n'));
  else if (kind === 'csv') cveSet(ws.cv, path, v.split(',').map(x => x.trim()).filter(Boolean));
  else if (kind === 'skills') cveSet(ws.cv, path, v.split(',').map(x => x.trim()).filter(Boolean).map(name => ({ name })));
  else if (kind === 'start' || kind === 'end') {
    const [start, end] = cvePeriodParts(cveGet(ws.cv, path));
    const next = kind === 'start' ? [v.trim(), end] : [start, v.trim()];
    cveSet(ws.cv, path, next[0] && next[1] ? `${next[0]} – ${next[1]}` : next[0] || next[1]);
  } else cveSet(ws.cv, path, v);
  // A project's description follows its bullets
  const pm = path.match(/^projects\.(\d+)\.bullets$/);
  if (pm) ws.cv.projects[pm[1]].desc = ws.cv.projects[pm[1]].bullets.filter(b => b.trim()).join(' ');
  ws.edited = true;
  cveRender(ws, 600);
}

function cveAction(ws, act, section, index) {
  const listOf = (name) => (ws.cv[name] = ws.cv[name] || []);
  const arr = listOf(section);
  const i = Number(index);
  if (act === 'add') arr.push(CVE_BLANK[section] ? CVE_BLANK[section]() : '');
  if (act === 'remove') arr.splice(i, 1);
  if (act === 'up' && i > 0) [arr[i - 1], arr[i]] = [arr[i], arr[i - 1]];
  if (act === 'down' && i < arr.length - 1) [arr[i + 1], arr[i]] = [arr[i], arr[i + 1]];
  ws.edited = true;
  renderEditor(ws);
  cveRender(ws, 150);
}

function cveOpen(ws, panel) {
  ws.open = ws.open === panel ? '' : panel;
  renderEditor(ws);
}

function renderEditor(ws) {
  const box = document.getElementById(ws.editorId);
  if (!box || !ws.cv) return;
  const cv = ws.cv;
  const w = `CVE_WS['${ws.key}']`;
  const v = (x) => escapeHtml(x == null ? '' : String(x));
  const field = (label, path, value, kind = 'text', ph = '', type = 'text') => `
    <label class="cve-field"><span>${label}</span><input class="input" type="${type}" data-f="${path}" data-t="${kind}" value="${v(value)}" placeholder="${v(ph)}" autocomplete="off"></label>`;
  const area = (label, path, value, kind = 'text', ph = '', rows = 4) => `
    <label class="cve-field cve-wide"><span>${label}</span><textarea class="input" rows="${rows}" data-f="${path}" data-t="${kind}" placeholder="${v(ph)}">${v(value)}</textarea></label>`;
  const itemTools = (section, i, n) => `<div class="cve-tools">
    <button type="button" onclick="cveAction(${w}, 'up', '${section}', ${i})" ${i === 0 ? 'disabled' : ''} aria-label="Move up">↑</button>
    <button type="button" onclick="cveAction(${w}, 'down', '${section}', ${i})" ${i === n - 1 ? 'disabled' : ''} aria-label="Move down">↓</button>
    <button type="button" class="cve-remove" onclick="cveAction(${w}, 'remove', '${section}', ${i})">Remove</button></div>`;
  // "Ask AI to change this section": what's typed here changes this section only
  const AI_HINTS = {
    personal: 'e.g. "phone +92 300 1234567", "headline: Lead AI Engineer"',
    summary: 'e.g. "make it shorter", "mention that I work across AI and cloud", "improve it"',
    skills: 'e.g. "Kafka, Terraform" or "remove PHP"',
    experience: 'e.g. "led a team of 4 on the billing service", "improve these points", "add more skills here"',
    projects: 'e.g. "built a WhatsApp agent for 500 clinics", "remove the point about X"',
    education: 'e.g. "MSc Data Science, LUMS, 2020"',
    certifications: 'e.g. "AWS Certified Developer – Associate"'
  };
  const aiBox = (section, i = 0, what = 'this section') => {
    const key = `${section}:${i}`;
    const id = `cve-ai-${ws.key}-${section}-${i}`;
    return `<div class="cve-ai">
      <label class="cve-ai-label" for="${id}">Ask AI to change ${v(what)}</label>
      <div class="cve-ai-row">
        <textarea class="input cve-ai-box" id="${id}" rows="1" placeholder="${v(AI_HINTS[section])}" onkeydown="cveAiKey(event, '${ws.key}', '${section}', ${i})">${v(ws.aiDrafts[key] || '')}</textarea>
        <button type="button" class="btn btn-primary cve-ai-go" onclick="cveAiApply('${ws.key}', '${section}', ${i}, this)">Apply</button>
      </div>
      ${ws.aiNotes[key] ? `<div class="cve-ai-note">${ws.aiNotes[key]}</div>` : ''}
    </div>`;
  };
  const addBtn = (section, label) => `<button type="button" class="btn btn-secondary cve-add" onclick="cveAction(${w}, 'add', '${section}')">+ ${label}</button>`;

  const bodies = {
    personal: () => `<div class="cve-grid">
      ${field('Full name', 'name', cv.name, 'text', 'e.g. Amir Sharif')}
      ${field('Headline', 'headline', cv.headline, 'text', 'e.g. Senior AI Engineer')}
      ${field('Email', 'email', cv.email, 'text', 'you@example.com', 'email')}
      ${field('Phone', 'phone', cv.phone, 'text', '+92 300 0000000', 'tel')}
      ${field('Location', 'location', cv.location, 'text', 'City, Country')}
      ${field('LinkedIn', 'linkedin', cv.linkedin, 'text', 'linkedin.com/in/you')}
      ${field('GitHub', 'github', cv.github, 'text', 'github.com/you')}
      ${field('Key skills line', 'tagline', (cv.tagline || []).join(', '), 'csv', 'Python, LLMs, RAG, AWS')}
    </div><p class="cve-hint">The key skills line appears under the headline in layouts that have one.</p>${aiBox('personal', 0, 'your details')}`,
    summary: () => `${area('Summary', 'summary', cv.summary, 'text', '3–4 sentences about your experience and strengths.', 6)}${aiBox('summary', 0, 'the summary')}`,
    experience: () => `${(cv.experience || []).map((x, i, all) => {
      const [start, end] = cvePeriodParts(x.period);
      return `<div class="cve-item"><div class="cve-item-head"><strong>${v(x.role || 'New role')}${x.company ? ` · ${v(x.company)}` : ''}</strong>${itemTools('experience', i, all.length)}</div>
        <div class="cve-grid">
          ${field('Job title', `experience.${i}.role`, x.role)}
          ${field('Company', `experience.${i}.company`, x.company)}
          ${field('Start', `experience.${i}.period`, start, 'start', 'e.g. Mar 2022')}
          ${field('End', `experience.${i}.period`, end, 'end', 'e.g. Present')}
          ${field('Location', `experience.${i}.location`, x.location, 'text', 'City, Country / Remote')}
        </div>
        ${area('Achievements — one per line', `experience.${i}.bullets`, (x.bullets || []).join('\n'), 'lines', 'Start each with a verb and include the result.', 5)}
        ${aiBox('experience', i, `this job${x.company ? ` (${x.company})` : ''}`)}</div>`;
    }).join('')}${addBtn('experience', 'Add role')}`,
    education: () => `${(cv.education || []).map((e, i, all) => `<div class="cve-item"><div class="cve-item-head"><strong>${v(e.degree || 'New entry')}</strong>${itemTools('education', i, all.length)}</div>
        <div class="cve-grid">
          ${field('Degree', `education.${i}.degree`, e.degree, 'text', 'e.g. BSc Computer Science')}
          ${field('School', `education.${i}.school`, e.school)}
          ${field('Dates', `education.${i}.period`, e.period, 'text', 'e.g. 2014 – 2018')}
        </div></div>`).join('')}${addBtn('education', 'Add education')}${aiBox('education', 0, 'your education')}`,
    skills: () => `${(cv.skills || []).map((g, i, all) => `<div class="cve-item"><div class="cve-item-head"><strong>${v(g.group || 'New group')}</strong>${itemTools('skills', i, all.length)}</div>
        <div class="cve-grid">
          ${field('Category', `skills.${i}.group`, g.group, 'text', 'e.g. Languages')}
        </div>
        ${area('Skills — separated by commas', `skills.${i}.items`, (g.items || []).map(s => (typeof s === 'string' ? s : s.name)).join(', '), 'skills', 'Python, TypeScript, SQL', 2)}</div>`).join('')}${addBtn('skills', 'Add skill group')}${aiBox('skills', 0, 'your skills')}`,
    projects: () => `${(cv.projects || []).map((pr, i, all) => `<div class="cve-item"><div class="cve-item-head"><strong>${v(pr.name || 'New project')}</strong>${itemTools('projects', i, all.length)}</div>
        <div class="cve-grid">
          ${field('Project name', `projects.${i}.name`, pr.name)}
          ${field('Technologies', `projects.${i}.tech`, (pr.tech || []).join(', '), 'csv', 'Next.js, Python')}
        </div>
        ${area('Description — one point per line', `projects.${i}.bullets`, (pr.bullets && pr.bullets.length ? pr.bullets : [pr.desc || '']).join('\n'), 'lines', 'What it is and what you built.', 3)}
        ${aiBox('projects', i, `this project${pr.name ? ` (${pr.name})` : ''}`)}</div>`).join('')}${addBtn('projects', 'Add project')}`,
    certifications: () => `${area('Certifications — one per line', 'certifications', (cv.certifications || []).join('\n'), 'lines', 'e.g. AWS Certified Developer — Amazon Web Services (2022)', 4)}${aiBox('certifications', 0, 'your certifications')}`
  };

  box.innerHTML = CVE_PANELS.map(([id, label]) => `
    <div class="cve-panel${ws.open === id ? ' open' : ''}">
      <button type="button" class="cve-panel-head" aria-expanded="${ws.open === id}" onclick="cveOpen(${w}, '${id}')"><span>${label}</span><span class="cve-chevron">▾</span></button>
      ${ws.open === id ? `<div class="cve-panel-body">${bodies[id]()}</div>` : ''}
    </div>`).join('');
}

// Typing in any editor field updates that workspace's CV
document.addEventListener('input', (e) => {
  const el = e.target.closest('[data-f]');
  if (!el) return;
  const ws = Object.values(CVE_WS).find(x => el.closest(`#${x.editorId}`));
  if (ws) cveField(ws, el);
});

const CVE_WS = { tailor: tailorWs, own: ownWs };

// ---------- Tailor CV: edit the tailored CV ----------

// Called after each tailoring run
function cveLoadTailored(result) {
  tailorWs.cv = JSON.parse(JSON.stringify(result.cv));
  tailorWs.result = result;
  tailorWs.layout = typeof tailorLayout !== 'undefined' ? tailorLayout : result.template;
  tailorWs.edited = false;
  if (typeof instructLoaded === 'function') instructLoaded(result);
  renderStyleBar(tailorWs);
  if (!document.getElementById('tailor-edit-card').hidden) renderEditor(tailorWs);
}

function toggleTailorEditor() {
  const card = document.getElementById('tailor-edit-card');
  card.hidden = !card.hidden;
  if (!card.hidden) {
    renderEditor(tailorWs);
    card.scrollIntoView({ behavior: 'smooth', block: 'start' });
  }
}

// ---------- CV Editor tab: your own CV ----------

const draftKey = () => `kairo.cvDraft.${typeof activeProfile !== 'undefined' ? activeProfile : 'default'}`;
let cveDraftTimer = null;

function cveSaveDraft(ws) {
  clearTimeout(cveDraftTimer);
  cveDraftTimer = setTimeout(() => {
    try {
      localStorage.setItem(draftKey(), JSON.stringify({ cv: ws.cv, styles: ws.styles, layout: ws.layout, savedAt: new Date().toISOString() }));
      const note = document.getElementById('own-draft-note');
      if (note) note.textContent = `Draft saved on this device at ${new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}.`;
    } catch (e) { /* storage full or blocked: the editor still works */ }
  }, 400);
}

function cveReadDraft() {
  try { return JSON.parse(localStorage.getItem(draftKey()) || 'null'); } catch (e) { return null; }
}

// Opens the CV Editor: the saved draft if there is one, otherwise the profile
async function openCvEditor() {
  if (ownWs.cv && ownWs.profile === activeProfile) return;
  const draft = cveReadDraft();
  if (draft && draft.cv) {
    ownWs.cv = draft.cv;
    ownWs.styles = draft.styles || {};
    ownWs.layout = draft.layout || ownWs.layout;
    ownWs.profile = activeProfile;
    cveShowOwn();
    renderEditor(ownWs);
    cveRender(ownWs, 0);
    return;
  }
  await ownStartFromProfile(true);
}

async function ownStartFromProfile(silent) {
  if (!silent && ownWs.cv && !confirm('Replace the CV in the editor with a fresh copy of your profile?')) return;
  try {
    const res = await fetch(apiUrl('/api/cv/from-profile'));
    const data = await res.json();
    if (!res.ok) throw new Error(data.error || 'Could not load your profile');
    ownWs.cv = data.cv;
    ownWs.result = data;
    ownWs.profile = activeProfile;
    ownWs.open = 'personal';
    cveShowOwn();
    renderEditor(ownWs);
    renderStyleBar(ownWs);
    renderOwnPreview();
    cveSaveDraft(ownWs);
    if (!silent) showToast('Loaded your profile into the editor');
  } catch (err) {
    showToast(err.message || 'Could not load your profile');
    if (!ownWs.cv) ownStartBlank(true);
  }
}

function ownStartBlank(silent) {
  if (!silent && ownWs.cv && !confirm('Start a blank CV? The current draft will be replaced.')) return;
  ownWs.cv = cveBlankCV();
  ownWs.profile = activeProfile;
  ownWs.open = 'personal';
  cveShowOwn();
  renderEditor(ownWs);
  cveRender(ownWs, 0);
}

function cveShowOwn() {
  document.getElementById('own-workspace').hidden = false;
}

// A different profile has its own draft
function cveProfileChanged() {
  ownWs.cv = null;
  ownWs.result = null;
  ownWs.styles = {};
  if (document.getElementById('tab-cv-editor').classList.contains('active')) openCvEditor();
}

function ownLayout() {
  const layouts = (ownWs.result && ownWs.result.layouts) || {};
  return layouts[ownWs.layout] || Object.values(layouts)[0] || null;
}

function renderOwnPreview() {
  const layout = ownLayout();
  const select = document.getElementById('own-layout');
  const layouts = (ownWs.result && ownWs.result.layouts) || {};
  select.innerHTML = Object.entries(layouts).map(([id, l]) => `<option value="${escapeHtml(id)}"${id === ownWs.layout ? ' selected' : ''}>${escapeHtml(l.label)}</option>`).join('');
  renderStyleBar(ownWs);
  if (!layout) return;
  const frame = document.getElementById('own-frame');
  frame.srcdoc = cvDocument(layout.html, `${ownWs.cv.name || 'CV'} - CV`, false, layout.css);
  frame.onload = () => { frame.style.height = `${frame.contentDocument.documentElement.scrollHeight}px`; };
}

function setOwnLayout(id) {
  ownWs.layout = id;
  ownWs.menu = null;
  renderOwnPreview();
  cveSaveDraft(ownWs);
}

function ownDownloadTex() {
  const layout = ownLayout();
  if (!layout) return;
  cveSaveFile(new Blob([layout.latex], { type: 'application/x-tex' }), `${cveFileBase(ownWs.cv)}.tex`);
}

function ownCopyText() {
  if (!ownWs.result) return;
  navigator.clipboard.writeText(ownWs.result.text || '').then(() => showToast('CV copied as plain text')).catch(() => showToast('Copy failed'));
}

// ---------- Downloads ----------

function cveFileBase(cv) {
  return `${(cv && cv.name) || 'CV'}`.replace(/[^A-Za-z0-9 _-]+/g, '').trim().replace(/\s+/g, '_') + '_CV';
}

function cveSaveFile(blob, name) {
  const link = document.createElement('a');
  link.href = URL.createObjectURL(blob);
  link.download = name;
  document.body.appendChild(link);
  link.click();
  link.remove();
  setTimeout(() => URL.revokeObjectURL(link.href), 1000);
}

// Real PDF compiled from the LaTeX layout on the server; falls back to printing the preview
async function cveDownloadPdf(ws, button, fallback) {
  if (!ws.cv) return;
  const label = button ? button.innerHTML : '';
  if (button) { button.disabled = true; button.textContent = 'Building PDF…'; }
  try {
    const job = ws.job();
    const res = await fetch(apiUrl('/api/cv/pdf'), {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ cv: ws.cv, styles: ws.styles, template: ws.layout, job: { title: job.title || '', company: job.company || '' } })
    });
    if (!res.ok) {
      const data = await res.json().catch(() => ({}));
      throw new Error(data.error || 'Could not build the PDF');
    }
    cveSaveFile(await res.blob(), `${cveFileBase(ws.cv)}.pdf`);
    showToast('PDF downloaded');
  } catch (err) {
    showToast(`${err.message} Opening print instead…`, 5000);
    if (fallback) fallback();
  } finally {
    if (button) { button.disabled = false; button.innerHTML = label; }
  }
}

function ownPrintPdf() {
  const layout = ownLayout();
  if (!layout) return;
  const frame = document.createElement('iframe');
  frame.style.cssText = 'position:fixed;right:0;bottom:0;width:0;height:0;border:0;';
  document.body.appendChild(frame);
  frame.srcdoc = cvDocument(layout.html, `${ownWs.cv.name || 'CV'} - CV`, false, layout.css);
  frame.onload = () => setTimeout(() => { frame.contentWindow.focus(); frame.contentWindow.print(); setTimeout(() => frame.remove(), 1000); }, 400);
}

// ---------- "Ask AI to change this section" ----------

// Enter applies; Shift+Enter starts a new line
function cveAiKey(e, key, section, i) {
  if (e.key !== 'Enter' || e.shiftKey || e.isComposing) return;
  e.preventDefault();
  const btn = e.target.closest('.cve-ai').querySelector('.cve-ai-go');
  if (btn && !btn.disabled) cveAiApply(key, section, i, btn);
}

async function cveAiApply(key, section, i, btn) {
  const ws = CVE_WS[key];
  const noteKey = `${section}:${i}`;
  const box = document.getElementById(`cve-ai-${key}-${section}-${i}`);
  const text = box ? box.value.trim() : '';
  if (!ws || !ws.cv) return;
  if (!text) { if (box) box.focus(); return; }
  const done = (html) => { ws.aiNotes[noteKey] = html; renderEditor(ws); };
  const before = JSON.parse(JSON.stringify(ws.cv));
  // Summary: "improve it" / "rewrite it" = the summary Kairo wrote for this job (Tailor page)
  if (section === 'summary' && key === 'tailor' && typeof instructBaseSummary === 'string' && instructBaseSummary
    && /^(?:please\s+)?(?:improve|rewrite|regenerate|generate|redo|polish|refresh|better|tailor)(?:\s+(?:it|this|the summary|my summary))?(?:\s+for (?:this|the) (?:job|jd|role))?[.!]*$/i.test(text)) {
    ws.aiUndo.push(before);
    if (typeof instructUndo !== 'undefined') { instructUndo.push(before); updateInstructUndo(); }
    ws.cv.summary = instructBaseSummary;
    ws.edited = true;
    ws.aiDrafts[noteKey] = '';
    done(`<ul class="instruct-done"><li>Rewrote the summary for this job.</li></ul><button type="button" class="btn-link" onclick="cveAiUndo('${key}', '${noteKey}')">Undo</button>`);
    cveRender(ws, 0);
    return;
  }
  btn.disabled = true;
  btn.textContent = 'Working…';
  ws.aiNotes[noteKey] = '<p class="instruct-wait">Working on it… requests in your own words can take up to a minute with the local AI.</p>';
  const note = btn.closest('.cve-ai').querySelector('.cve-ai-note');
  if (note) note.innerHTML = ws.aiNotes[noteKey];
  else btn.closest('.cve-ai').insertAdjacentHTML('beforeend', `<div class="cve-ai-note">${ws.aiNotes[noteKey]}</div>`);
  try {
    const res = await fetch(apiUrl('/api/cv/instruct'), {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ cv: ws.cv, text, scope: { section, index: i }, job: ws.job() })
    });
    const data = await res.json();
    if (!res.ok) throw new Error(data.error || 'Could not apply that');
    if (data.done.length) {
      ws.aiUndo.push(before);
      if (key === 'tailor' && typeof instructUndo !== 'undefined') { instructUndo.push(before); updateInstructUndo(); }
      ws.cv = data.cv;
      ws.edited = true;
      for (const skill of data.skills || []) if (key === 'tailor' && typeof instructConfirmSkill === 'function') instructConfirmSkill(skill);
      cveRender(ws, 0);
    }
    // what wasn't understood stays in the box
    ws.aiDrafts[noteKey] = data.done.length ? '' : text;
    done((data.done.length ? `<ul class="instruct-done">${data.done.map(d => `<li>${escapeHtml(d)}</li>`).join('')}</ul><button type="button" class="btn-link" onclick="cveAiUndo('${key}', '${noteKey}')">Undo</button>` : '')
      + (data.unclear.length ? `<div class="instruct-unclear"><strong>Not changed:</strong><ul>${data.unclear.map(u => `<li>${escapeHtml(u)}</li>`).join('')}</ul>${data.ai ? 'Try describing it a different way.' : 'Try one of the examples above.'}</div>` : ''));
  } catch (err) {
    ws.aiDrafts[noteKey] = text;
    done(`<div class="instruct-unclear">${escapeHtml(err.message || 'Could not reach the server')}</div>`);
  }
}

function cveAiUndo(key, noteKey) {
  const ws = CVE_WS[key];
  if (!ws || !ws.aiUndo.length) return;
  ws.cv = ws.aiUndo.pop();
  if (key === 'tailor' && typeof instructUndo !== 'undefined' && instructUndo.length) { instructUndo.pop(); updateInstructUndo(); }
  ws.aiNotes[noteKey] = '<ul class="instruct-done"><li>Undid that change.</li></ul>';
  renderEditor(ws);
  cveRender(ws, 0);
}


// Tailor CV: "Tell it what to add or change". After tailoring, type plain instructions
// ("Under Brightloop add: …", "Add skills: Kubernetes", "Remove PHP", "Change headline
// to …") and they are applied to the CV; the preview, CV match, review and downloads
// follow. Suggestions above the box point at what to improve for this job; clicking one
// starts the instruction for you. Also: reading the job description from a file.

let instructUndo = [];   // earlier versions of the CV, for "Undo last change"

// Called after each tailoring run
let instructBaseSummary = '';   // the summary Kairo wrote for this job

function instructLoaded(result) {
  instructUndo = [];
  instructBaseSummary = (result && result.cv && result.cv.summary) || '';
  const box = document.getElementById('tailor-instruct');
  if (box) box.value = '';
  setInstructResult('');
  updateInstructUndo();
  renderInstructTips();
}

// After any change to the CV (Edit CV, the style bar, an instruction): refresh the suggestions
function instructSync() {
  renderInstructTips();
}

function updateInstructUndo() {
  const btn = document.getElementById('tailor-instruct-undo');
  if (btn) btn.disabled = !instructUndo.length;
}

function setInstructResult(html) {
  const el = document.getElementById('tailor-instruct-result');
  if (el) el.innerHTML = html;
}

async function applyInstruct(button) {
  const box = document.getElementById('tailor-instruct');
  const text = box.value.trim();
  if (!tailorWs.cv) return;
  if (!text) {
    showToast('Write what you want to add or change first');
    box.focus();
    return;
  }
  // "Generate a summary for this JD": the summary Kairo wrote for this job, straight away
  const allLines = text.split('\n').map(l => l.trim()).filter(Boolean);
  const wantSummary = allLines.filter(isSummaryRequest);
  if (wantSummary.length && instructBaseSummary) {
    if (tailorWs.cv.summary !== instructBaseSummary) {
      instructUndo.push(JSON.parse(JSON.stringify(tailorWs.cv)));
      tailorWs.cv.summary = instructBaseSummary;
      tailorWs.edited = true;
      if (!document.getElementById('tailor-edit-card').hidden) renderEditor(tailorWs);
      cveRender(tailorWs, 0);
      updateInstructUndo();
    }
  }
  const summaryNote = wantSummary.length ? `<ul class="instruct-done"><li>${instructBaseSummary ? 'Your summary is the one written for this job' : 'Tailor the CV first to get a summary for this job'}: "${escapeHtml(instructBaseSummary.slice(0, 160))}${instructBaseSummary.length > 160 ? '…' : ''}"</li></ul>` : '';
  // Questions ("what am I missing?") are answered here from the CV review
  const lines = allLines.filter(l => !isSummaryRequest(l));
  if (!lines.length) {
    box.value = '';
    setInstructResult(summaryNote);
    return;
  }
  const questions = lines.filter(isInstructQuestion);
  const changes = lines.filter(l => !isInstructQuestion(l));
  if (questions.length && !changes.length) {
    box.value = '';
    setInstructResult(summaryNote + questions.map(q => `<div class="instruct-answer"><strong>${escapeHtml(q)}</strong><p>${answerInstructQuestion(q)}</p></div>`).join(''));
    return;
  }
  button.disabled = true;
  button.textContent = 'Working on it…';
  setInstructResult('<p class="instruct-wait">Working on it… requests in your own words can take up to a minute with the local AI.</p>');
  try {
    const res = await fetch(apiUrl('/api/cv/instruct'), {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      // the job too, so changes can be tailored to it
      body: JSON.stringify({ cv: tailorWs.cv, text: changes.join('\n'), job: { title: document.getElementById('tailor-title').value.trim(), description: document.getElementById('tailor-desc').value.trim() } })
    });
    const data = await res.json();
    if (!res.ok) throw new Error(data.error || 'Could not apply that');
    if (data.done.length) {
      instructUndo.push(JSON.parse(JSON.stringify(tailorWs.cv)));
      tailorWs.cv = data.cv;
      tailorWs.edited = true;
      // Skills you added count as yours for this job
      for (const skill of data.skills || []) instructConfirmSkill(skill);
      if (!document.getElementById('tailor-edit-card').hidden) renderEditor(tailorWs);
      cveRender(tailorWs, 0);
    }
    // Keep only the original request (not the explanation) in the box, to fix and try again
    box.value = (data.pending && data.pending.length ? data.pending : data.unclear).join('\n');
    setInstructResult(
      summaryNote + questions.map(q => `<div class="instruct-answer"><strong>${escapeHtml(q)}</strong><p>${answerInstructQuestion(q)}</p></div>`).join('')
      + (data.done.length ? `<ul class="instruct-done">${data.done.map(d => `<li>${escapeHtml(d)}</li>`).join('')}</ul>` : '')
      + (data.unclear.length ? `<div class="instruct-unclear"><strong>Not changed</strong> (left in the box):<ul>${data.unclear.map(u => `<li>${escapeHtml(u)}</li>`).join('')}</ul>${data.ai ? 'Try describing it a different way — say exactly what you did, or name the job or section.' : 'Try one of the examples below. For anything else, I need the local AI (Ollama) running, or an Anthropic API key added.'}</div>` : ''));
  } catch (err) {
    showToast(err.message || 'Could not reach the server');
  } finally {
    button.disabled = false;
    button.textContent = 'Apply to CV';
    updateInstructUndo();
  }
}

function undoInstruct() {
  if (!instructUndo.length) return;
  tailorWs.cv = instructUndo.pop();
  if (!document.getElementById('tailor-edit-card').hidden) renderEditor(tailorWs);
  cveRender(tailorWs, 0);
  setInstructResult('<ul class="instruct-done"><li>Undid the last change.</li></ul>');
  updateInstructUndo();
}

// A skill added by instruction moves from "Not in your profile" to "Covered"
function instructConfirmSkill(skill) {
  const a = tailorResult && tailorResult.analysis;
  if (!a) return;
  const i = a.missing.findIndex(m => m.name.toLowerCase() === skill.toLowerCase());
  if (i < 0) return;
  const m = a.missing.splice(i, 1)[0];
  tailorConfirmed.add(m.name);
  a.matched.push({ name: m.name, required: m.required, soft: m.soft, confirmed: true, implied: null });
  const req = a.matched.filter(x => x.required).length;
  const total = req + a.missing.filter(x => x.required).length;
  if (total) a.matchScore = Math.round((req / total) * 100);
  renderTailorChips();
  renderTailorScore();
}

// ---------- Suggestions above the box ----------
// Plain pointers from the CV review. Clicking one writes the start of the instruction.

const MAX_INSTRUCT_TIPS = 6;

function instructTips() {
  const rv = tailorResult && tailorResult.review;
  if (!rv) return [];
  const tips = [];
  const seen = new Set();
  const add = (tip) => {
    const key = tip.key || tip.line || tip.text;
    if (seen.has(key)) return;
    seen.add(key);
    tips.push(tip);
  };
  const x = tailorWs.cv && tailorWs.cv.experience[0];
  const job = x ? (x.company || x.role) : '';
  const replace = (line) => `Replace "${line}" with "${line}"`;
  // Every job should have at least five points
  for (const j of ((tailorWs.cv && tailorWs.cv.experience) || []).filter(e => e.bullets.length < 5).slice(0, 3)) {
    const name = j.company || j.role;
    add({ key: `short:${name}`, text: `${[j.role, j.company].filter(Boolean).join(' at ')} has ${j.bullets.length} point${j.bullets.length === 1 ? '' : 's'}; every job should have at least 5. Add real ones from that job.`, prefill: `Under ${name}, add: ` });
  }
  for (const k of rv.recruiter.missingKeywords.filter(k => k.required && k.name !== 'AI').slice(0, 2)) {
    add({ key: `kw:${k.name}`, text: `The job asks for ${k.name}. If you've used it, add a point about it, or add it to your skills.`, prefill: job ? `Under ${job}, add: ` : 'Add a point: ' });
  }
  const contact = rv.recruiter.redFlags.find(f => /contact details/i.test(f.title));
  if (contact) add({ key: 'contact', text: contact.detail, prefill: /phone/i.test(contact.detail) ? 'Set phone to ' : 'Set email to ' });
  for (const b of (rv.xyz.weak || []).slice(0, 2)) add({ text: 'Start this point with what you did (Built, Led, Cut, Launched…), not a duty.', line: b.text, prefill: replace(b.text), select: true });
  for (const b of rv.xyz.needNumbers.slice(0, 3)) add({ text: 'Add a number to this point: how much, how many or how fast (only if you know it).', line: b.text, prefill: replace(b.text), select: true });
  for (const b of (rv.xyz.long || []).slice(0, 1)) add({ text: `Shorten this point to one or two lines (it has ${b.words} words).`, line: b.text, prefill: replace(b.text), select: true });
  for (const sec of rv.skim.sections) {
    if (sec.verdict === 'read' || !sec.fix || /^Experience|^Header/.test(sec.section)) continue;
    const prefill = sec.section === 'Skills' ? 'Add skills: ' : sec.section === 'Summary' ? 'Add to summary: ' : '';
    add({ key: sec.section, text: `${sec.section}: ${sec.reason} ${sec.fix}`, prefill });
  }
  for (const f of rv.recruiter.redFlags) {
    if (/required skill|contact details|measurable results|Duty-style|Dense bullets/i.test(f.title)) continue;
    add({ text: `${f.title}: ${f.fix}` });
  }
  return tips;
}

function renderInstructTips() {
  const box = document.getElementById('tailor-instruct-tips');
  if (!box) return;
  const tips = instructTips();
  window.__instructTips = tips;
  if (!tips.length) {
    box.innerHTML = '<p class="cv-tips-ok">Looks good: nothing major to fix for this job.</p>';
    return;
  }
  const shown = tips.slice(0, MAX_INSTRUCT_TIPS);
  const quote = (t) => (t.line ? `<span class="cv-tip-line">${escapeHtml(t.line.length > 90 ? `${t.line.slice(0, 90)}…` : t.line)}</span>` : '');
  box.innerHTML = `<p class="cv-tips-title">Suggestions <span>${tips.length}</span></p><ol class="cv-tips">${shown.map((t, i) => `
    <li><button type="button" class="cv-tip" onclick="useInstructTip(${i})"${t.prefill ? ' title="Start this change in the box below"' : ' disabled'}>
      <span class="cv-tip-text">${escapeHtml(t.text)}</span>${quote(t)}</button></li>`).join('')}</ol>${tips.length > MAX_INSTRUCT_TIPS ? `<p class="cv-tips-more">${tips.length - MAX_INSTRUCT_TIPS} more after you fix these.</p>` : ''}`;
}

// Start the instruction for a suggestion in the box (on a new line if there's text)
function useInstructTip(i) {
  const tip = (window.__instructTips || [])[i];
  const box = document.getElementById('tailor-instruct');
  if (!tip || !tip.prefill || !box) return;
  const before = box.value.replace(/\s+$/, '');
  box.value = before ? `${before}\n${tip.prefill}` : tip.prefill;
  box.focus();
  if (tip.select) {
    // select the second copy of the point, the part to rewrite
    const end = box.value.length - 1;
    const start = end - tip.line.length;
    box.setSelectionRange(start, end);
  } else box.setSelectionRange(box.value.length, box.value.length);
  box.scrollIntoView({ behavior: 'smooth', block: 'center' });
}

// ---------- Upload the job description ----------

async function handleTailorJdFile(input) {
  const file = input.files && input.files[0];
  input.value = '';
  if (!file) return;
  if (file.size > CV_MAX_BYTES) {
    showToast('That file is too large (10 MB at most).');
    return;
  }
  const desc = document.getElementById('tailor-desc');
  if (desc.value.trim() && !confirm('Replace the job description you already have?')) return;
  try {
    const text = String(await extractCvText(file)).replace(/\r/g, '').replace(/\n{3,}/g, '\n\n').trim();
    if (text.length < 40) throw new Error('Could not read much text from that file. Paste the job description instead.');
    desc.value = text;
    // The first line of a job description is usually the job title
    const title = document.getElementById('tailor-title');
    const first = text.split('\n').map(l => l.trim()).find(Boolean) || '';
    if (!title.value.trim() && first.length <= 80 && !/[.:]$/.test(first)) title.value = first;
    showToast(`Read the job description from ${file.name}`);
  } catch (err) {
    showToast(typeof friendlyCvError === 'function' ? friendlyCvError(err) : err.message, 7000);
  }
}

// "What can I write?": the + next to an example puts it in the box (with your latest
// job's name in place of the example's), ready to finish and apply
function addInstructExample(btn) {
  const box = document.getElementById('tailor-instruct');
  if (!box) return;
  const x = tailorWs.cv && tailorWs.cv.experience[0];
  const job = x ? (x.company || x.role) : '';
  let text = btn.dataset.text || '';
  if (text.includes('{job}')) text = job ? text.replace('{job}', job) : (text.startsWith('Under') ? 'Add a point: ' : 'I ');
  const before = box.value.replace(/\s+$/, '');
  box.value = before ? `${before}\n${text}` : text;
  box.focus();
  const select = btn.dataset.select;
  if (select) {
    const start = box.value.lastIndexOf(select);
    box.setSelectionRange(start, start + select.length);
  } else box.setSelectionRange(box.value.length, box.value.length);
  box.scrollIntoView({ behavior: 'smooth', block: 'center' });
}

// Enter applies what's in the box straight away; Shift+Enter starts a new line
function instructKey(e) {
  if (e.key !== 'Enter' || e.shiftKey || e.isComposing) return;
  e.preventDefault();
  const btn = document.getElementById('tailor-instruct-apply');
  if (btn && !btn.disabled) applyInstruct(btn);
}

// ---------- Questions typed in the box ----------

// "What am I missing?" is a question; "Can you add Kafka to my skills?" is a change
const INSTRUCT_ACTION = /\b(?:add|remove|delete|change|make|put|set|update|replace|rewrite|mention|highlight|include|insert|drop|get rid|move|shorten|organi[sz]e|write|rename|list|use)\b/i;
function isInstructQuestion(line) {
  if (/^(?:what|which|how|why|where|who|tell me|show me|explain)\b/i.test(line)) return true;
  if (/^(?:can|could|would|will)\s+(?:you|u)\b|^(?:please|pls|kindly)\b/i.test(line)) return !INSTRUCT_ACTION.test(line) && /\?\s*$/.test(line);
  if (/^(?:is|am|are|do|does|did|should|can|could)\b/i.test(line)) return true;
  return /\?\s*$/.test(line) && !INSTRUCT_ACTION.test(line.split(/\s+/).slice(0, 3).join(' '));
}

// An answer from this CV's review: score, gaps, red flags, what to improve, length
function answerInstructQuestion(q) {
  const r = tailorResult;
  if (!r || !r.review) return 'Tailor a CV first, then ask again.';
  const rv = r.review;
  const a = r.analysis;
  const list = (xs) => xs.map(x => escapeHtml(x)).join(', ');
  const missingReq = a.missing.filter(m => m.required && !m.soft).map(m => m.name);
  const missingNice = a.missing.filter(m => !m.required && !m.soft && !m.note).map(m => m.name);
  const tips = (typeof instructTips === 'function' ? instructTips() : []).slice(0, 3).map(t => escapeHtml(t.text));
  const score = `CV match <strong>${r.coverage ? r.coverage.cvScore : a.matchScore}%</strong>, recruiter score <strong>${escapeHtml(rv.recruiter.score)}/100</strong> (${rv.recruiter.parts.map(p => `${escapeHtml(p.label)} ${escapeHtml(p.points)}${p.of ? `/${p.of}` : ''}`).join(', ')}).`;
  const gaps = missingReq.length ? `The job asks for ${list(missingReq)}, which your CV doesn't show.${missingNice.length ? ` Nice to have: ${list(missingNice)}.` : ''} If you have any of them, write e.g. "Add skills: ${escapeHtml(missingReq[0])}".` : `Nothing the job requires is missing.${missingNice.length ? ` Nice to have: ${list(missingNice)}.` : ''}`;
  const flags = rv.recruiter.redFlags.length ? rv.recruiter.redFlags.map(f => `${escapeHtml(f.title)}: ${escapeHtml(f.detail)}`).join(' ') : 'No red flags a recruiter would spot in 10 seconds.';
  if (/\b(score|match|rating|percent|%|how good|how strong|good enough|ready|chance|fit)\b/i.test(q)) return `${score} ${missingReq.length ? gaps : ''}`;
  if (/\b(missing|gap|lack|need|require|skills?|keywords?)\b/i.test(q)) return gaps;
  if (/\b(red flags?|problems?|issues?|wrong|weak|bad)\b/i.test(q)) return flags;
  if (/\b(long|length|pages?|short)\b/i.test(q)) return `About ${escapeHtml(rv.skim.pages)} page${rv.skim.pages > 1 ? 's' : ''}. Write "Make it one page" to shorten it.`;
  if (/\b(improve|better|stronger|tips?|suggest|advice|change|fix)\b/i.test(q)) return tips.length ? `Top things to do: ${tips.map((t, i) => `${i + 1}. ${t}`).join(' ')}` : 'It already looks strong for this job.';
  return `${score} ${gaps} ${tips.length ? `Next: ${tips[0]}` : ''}`;
}

// "Generate (a generic / new / profile) summary (for this JD)", "write my summary for this job"
function isSummaryRequest(line) {
  return /^(?:please\s+|can you\s+|could you\s+)?(?:generate|regenerate|write|rewrite|create|make|give(?:\s+me)?|redo|refresh|build|draft|improve|strengthen|enhance|polish|refine|tighten|fix)\s+(?:me\s+)?(?:a\s+|an\s+|the\s+|my\s+)?(?:new\s+|generic\s+|fresh\s+|tailored\s+|proper\s+|better\s+|good\s+|strong\s+)*(?:profile\s+|professional\s+|cv\s+)?summary(?:\s+(?:for|to match|matching|based on|according to)\s+(?:this|the|my)\s+(?:jd|job|job description|role|position|posting))?[.!?]*$/i.test(line);
}


// Pipeline: "Ask AI" on each application card. Same idea as the CV editor's per-section
// boxes — say a short sentence, only that card changes, instantly (no AI model needed for
// the common phrasings: this is plain rules, not a network call). Covers moving stages,
// adding a note, setting who to contact, and a follow-up date.

const STATUS_WORDS = [
  [/\b(?:drafted?|draft(?:ing)?)\b/i, 'drafted'],
  [/\b(?:applied|submit(?:ted)?|sent (?:the|my) application)\b/i, 'applied'],
  [/\b(?:screen(?:ing)?|phone screen)\b/i, 'screening'],
  [/\b(?:interview(?:ing)?)\b/i, 'interview'],
  [/\b(?:offer(?:ed)?|got an offer)\b/i, 'offer'],
  [/\b(?:hired|accepted|started)\b/i, 'hired'],
  [/\b(?:rejected|reject(?:ion)?|closed|declined|turned down|didn'?t get it|no longer (?:in )?consideration|ghosted)\b/i, 'rejected']
];
const STATUS_NAMES = { drafted: 'Drafted', applied: 'Applied', screening: 'Screening', interview: 'Interview', offer: 'Offer', hired: 'Hired', rejected: 'Closed' };

// A short sentence with nothing concrete in it ("make some real-time improvements",
// "optimize this") should never be saved as a real note — only a vague instruction about
// the card itself slips through here; a genuine note like "called, left voicemail" always
// has something concrete (a name, an action with an object, a date) once these are stripped.
const VAGUE_WORDS = new Set([
  'add', 'added', 'adding', 'put', 'make', 'made', 'makes', 'making', 'do', 'did', 'does', 'doing',
  'try', 'tried', 'trying', 'some', 'something', 'anything', 'nothing', 'things', 'thing', 'stuff',
  'this', 'that', 'these', 'those', 'it', 'them', 'the', 'and', 'for', 'with', 'from', 'into', 'onto', 'about',
  'improve', 'improved', 'improvement', 'improvements', 'change', 'changed', 'changes',
  'update', 'updated', 'updates', 'edit', 'edited', 'edits', 'enhance', 'enhanced', 'enhancement', 'enhancements',
  'fix', 'fixed', 'fixes', 'tweak', 'tweaked', 'tweaks', 'optimize', 'optimise', 'optimized', 'optimised',
  'optimization', 'optimisation', 'better', 'stronger', 'best', 'good', 'nice', 'useful', 'helpful', 'relevant',
  'real', 'realtime', 'time', 'please', 'also', 'just', 'now', 'here', 'there', 'up', 'out', 'more'
]);
function isVagueRequest(text) {
  if (/\d/.test(text)) return false;
  const words = String(text).toLowerCase().replace(/[^a-z0-9\s]/g, ' ').split(/\s+/).filter(Boolean);
  if (!words.length) return true;
  return words.filter(w => w.length > 2 && !VAGUE_WORDS.has(w)).length === 0;
}

// "Friday", "next Friday", "tomorrow", "in 3 days", "Oct 20", "10/20", "2026-10-20"
const WEEKDAYS = ['sunday', 'monday', 'tuesday', 'wednesday', 'thursday', 'friday', 'saturday'];
const MONTHS = ['jan', 'feb', 'mar', 'apr', 'may', 'jun', 'jul', 'aug', 'sep', 'oct', 'nov', 'dec'];
function parseWhen(text, now = new Date()) {
  const t = String(text).trim().toLowerCase();
  const iso = (d) => `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
  const add = (n) => { const d = new Date(now); d.setDate(d.getDate() + n); return iso(d); };
  if (/^today$/.test(t)) return add(0);
  if (/^tomorrow$/.test(t)) return add(1);
  let m = t.match(/^in\s+(\d+)\s+days?$/);
  if (m) return add(Number(m[1]));
  m = t.match(/^(next\s+)?(sunday|monday|tuesday|wednesday|thursday|friday|saturday)$/);
  if (m) {
    const target = WEEKDAYS.indexOf(m[2]);
    let delta = (target - now.getDay() + 7) % 7;
    // "next Friday" always means next week's, even if this week's hasn't happened yet;
    // a bare "Friday" means the next upcoming one (today, if today is Friday)
    if (m[1]) delta += 7;
    return add(delta);
  }
  m = t.match(/^(\d{4})-(\d{2})-(\d{2})$/);
  if (m) return t;
  m = t.match(/^(\d{1,2})\/(\d{1,2})(?:\/(\d{2,4}))?$/);
  if (m) { const y = m[3] ? (m[3].length === 2 ? `20${m[3]}` : m[3]) : now.getFullYear(); return `${y}-${m[1].padStart(2, '0')}-${m[2].padStart(2, '0')}`; }
  m = t.match(/^([a-z]{3,9})\s+(\d{1,2})(?:,?\s*(\d{4}))?$/);
  if (m) {
    const mi = MONTHS.indexOf(m[1].slice(0, 3));
    if (mi >= 0) return `${m[3] || now.getFullYear()}-${String(mi + 1).padStart(2, '0')}-${String(Number(m[2])).padStart(2, '0')}`;
  }
  return null;
}

/**
 * Apply plain instructions to one tracker row. Pure, no network call.
 * @param {any} row the application (company, role, status, notes, contact_person, deadline, …)
 * @param {string} text one or more instructions (one per line or separated by ";")
 * @returns {{ row: any, done: string[], unclear: string[] }}
 */
function applyTrackerInstruction(row, text) {
  const out = { ...row };
  const done = [], unclear = [];
  // Two instructions in one sentence: "mark as interviewing, follow up Friday"
  const splitAt = /\s*,?\s+(?:and then|and also|then)\s+|\s*,\s+(?=(?:mark|move|set|status|add|note|contact|recruiter|follow|remind|next step|interview)\b)/i;
  const lines = String(text || '').split(/\n+|;\s*(?=[A-Za-z])/).flatMap(l => l.split(splitAt)).map(l => l.trim().replace(/^[-•*\s]+/, '')).filter(Boolean).slice(0, 10);
  for (const raw of lines) {
    let line = raw.replace(/^(?:please|pls|also|and|then|ok(?:ay)?|so)[,\s]+/i, '').trim();
    let m;
    // Status: "mark as interviewing", "move to offer", "we got an offer", "I got rejected"
    const hit = STATUS_WORDS.find(([re]) => re.test(line));
    if (hit && /\b(mark|move|set|status|stage|we|i|got|they|update)\b/i.test(line)) {
      out.status = hit[1];
      done.push(`Moved to ${STATUS_NAMES[hit[1]]}`);
      continue;
    }
    // Contact: "contact is Sarah", "recruiter is Sarah from HR", "set contact to Sarah"
    if ((m = line.match(/^(?:set\s+)?(?:the\s+|my\s+)?(?:contact|recruiter|hiring manager)\s+(?:is|to|=|:)\s*(.+)$/i))) {
      out.contact_person = m[1].trim().replace(/[.]$/, '');
      done.push(`Set the contact to ${out.contact_person}`);
      continue;
    }
    // Follow-up / deadline: "follow up Friday", "remind me next Friday", "next step: Oct 20"
    if ((m = line.match(/^(?:set\s+)?(?:a\s+|the\s+)?follow[\s-]?up(?:\s+(?:date|for|on))?\s*(?:is|to|:|=)?\s*(.+)$/i))
      || (m = line.match(/^remind me\s*(?:on|for)?\s*(.+)$/i))
      || (m = line.match(/^next step(?:\s+is)?\s*(?:on|:|=)?\s*(.+)$/i))
      || (m = line.match(/^interview(?:\s+is)?\s+(?:scheduled\s+)?(?:on|for)\s+(.+)$/i))) {
      const when = parseWhen(m[1].trim().replace(/[.]$/, ''));
      if (when) { out.deadline = when; done.push(`Follow-up set for ${when}`); }
      else unclear.push(`${raw} — I didn't understand "${m[1].trim()}" as a date. Try "Friday", "next Friday", "in 3 days" or "2026-10-20".`);
      continue;
    }
    // Notes: "add a note: ...", "note that ...", or any other short sentence
    if ((m = line.match(/^(?:add\s+(?:a\s+)?note\s*:?\s*|note(?:\s+that)?\s*:?\s*)(.+)$/i))) {
      const note = `${m[1].trim().replace(/[.]+$/, '')}.`;
      out.notes = out.notes ? `${out.notes}\n${note}` : note;
      done.push(`Added a note: "${note}"`);
      continue;
    }
    // Anything else short enough is treated as a note too, so "called, left voicemail" still
    // works — but only when it says something concrete; a vague instruction about the card
    // itself ("make some real-time improvements") must never be saved as if it were a note.
    if (line.split(/\s+/).length <= 25 && line.length >= 3 && !isVagueRequest(line)) {
      const note = `${line.replace(/[.]+$/, '')}.`;
      out.notes = out.notes ? `${out.notes}\n${note}` : note;
      done.push(`Added a note: "${note}"`);
      continue;
    }
    unclear.push(`${raw} — that doesn't say what to change. Try "mark as interviewing", "add a note: called recruiter today", "contact is Sarah", or "follow up Friday".`);
  }
  return { row: out, done, unclear };
}

// ---------- The box on each card ----------

let trackerAiOpen = null;   // index of the card whose box is open
let trackerAiUndo = {};     // idx -> previous row, for Undo
let trackerAiNotes = {};    // idx -> { done, unclear } from the last apply, survives re-render
let trackerAiDrafts = {};   // idx -> text left in the box (e.g. the unclear part, to fix and retry)

function toggleCardAi(idx) {
  trackerAiOpen = trackerAiOpen === idx ? null : idx;
  renderKanban();
  if (trackerAiOpen === idx) setTimeout(() => { const el = document.getElementById(`tracker-ai-${idx}`); if (el) el.focus(); }, 0);
}

function cardAiKey(e, idx) {
  if (e.key !== 'Enter' || e.shiftKey || e.isComposing) return;
  e.preventDefault();
  applyCardAi(idx);
}

async function applyCardAi(idx) {
  const box = document.getElementById(`tracker-ai-${idx}`);
  const text = box ? box.value.trim() : '';
  const app = applications[idx];
  if (!app) return;
  if (!text) { if (box) box.focus(); return; }
  const before = { ...app };
  const { row, done, unclear } = applyTrackerInstruction(app, text);
  if (done.length) {
    trackerAiUndo[idx] = before;
    applications[idx] = row;
    syncTrackerData();
    updateStats();
  }
  // kept in state (not just the DOM): renderKanban() below rebuilds this card's markup,
  // which would otherwise wipe a result written directly into the page
  trackerAiNotes[idx] = { done, unclear };
  trackerAiDrafts[idx] = unclear.length ? unclear.map(u => u.split(' — ')[0]).join('\n') : '';
  renderKanban();
}

function undoCardAi(idx) {
  if (!trackerAiUndo[idx]) return;
  applications[idx] = trackerAiUndo[idx];
  delete trackerAiUndo[idx];
  trackerAiNotes[idx] = { done: ['Undone.'], unclear: [] };
  syncTrackerData();
  updateStats();
  renderKanban();
}

/** Small toggle in the card's action row; always rendered. */
function cardAiToggle(idx) {
  return `<button class="btn-link" onclick="toggleCardAi(${idx})">${trackerAiOpen === idx ? 'Close AI' : 'Ask AI'}</button>`;
}

/** The expanded box, rendered as its own block below the card's actions when open. */
function cardAiPanel(idx) {
  if (trackerAiOpen !== idx) return '';
  const r = trackerAiNotes[idx];
  const noteHtml = r
    ? (r.done.length ? `<ul class="instruct-done">${r.done.map(d => `<li>${escapeHtml(d)}</li>`).join('')}</ul>${trackerAiUndo[idx] !== undefined ? `<button type="button" class="btn-link" onclick="undoCardAi(${idx})">Undo</button>` : ''}` : '')
      + (r.unclear.length ? `<div class="instruct-unclear"><ul>${r.unclear.map(u => `<li>${escapeHtml(u)}</li>`).join('')}</ul></div>` : '')
    : '';
  return `<div class="tracker-ai" onclick="event.stopPropagation()">
    <textarea class="input tracker-ai-box" id="tracker-ai-${idx}" rows="1" placeholder="e.g. mark as interviewing, follow up Friday, contact is Sarah" onkeydown="cardAiKey(event, ${idx})" onclick="event.stopPropagation()">${escapeHtml(trackerAiDrafts[idx] || '')}</textarea>
    <div class="tracker-ai-row"><button type="button" class="btn btn-primary btn-sm" onclick="applyCardAi(${idx})">Apply</button></div>
    <div class="instruct-note" id="tracker-ai-note-${idx}"${noteHtml ? '' : ' hidden'}>${noteHtml}</div>
  </div>`;
}


// Profile switcher and editor. Each profile has its own profile file and
// application tracker on the server; app.js scopes every request to
// `activeProfile` via apiUrl().

let profilesList = [];
let profilesLoadFailed = false;

async function initProfiles() {
  try {
    const res = await fetch('/api/profiles');
    if (res.ok) profilesList = await res.json();
    else profilesLoadFailed = true;
  } catch (e) {
    console.warn('Profiles unavailable', e);
    profilesLoadFailed = true;
  }
  if (!profilesList.some(p => p.id === activeProfile)) {
    activeProfile = 'default';
  }
  applyProfileIdentity();
  const current = currentProfile();
  if (current && !current.original) {
    document.getElementById('search-query-input').value = current.title;
  }
}

function currentProfile() {
  return profilesList.find(p => p.id === activeProfile) || null;
}

function applyProfileIdentity() {
  const p = currentProfile();
  const name = p ? (p.name || p.label) : 'Hassaan Nasir';
  const role = p ? p.title : 'Senior Full Stack & AI Engineer';
  const initials = p ? p.initials : 'HN';

  document.getElementById('side-avatar').textContent = initials;
  document.getElementById('side-name').textContent = name;
  document.getElementById('side-role').textContent = role;
  document.getElementById('top-avatar').textContent = initials;
  document.title = `Job Engine | ${name}`;
  // Hassaan's hand-written CV Studio, Interview and sample evaluation only show while
  // the main profile still holds his details (not after someone else's CV is imported)
  const original = !p || p.original ? 'true' : 'false';
  if (original === 'false' && document.body.dataset.builtin !== 'false') resetEvaluator();
  document.body.dataset.builtin = original;
  document.querySelectorAll('.profile-custom-name').forEach(el => { el.textContent = name; });
}

// ---------- Menu ----------

function toggleProfileMenu(anchor) {
  const menu = document.getElementById('profile-menu');
  if (!menu.hidden) {
    closeProfileMenu();
    return;
  }
  renderProfileMenu();
  menu.hidden = false;

  // Open above the sidebar card, or below the mobile avatar
  const rect = anchor.getBoundingClientRect();
  const width = Math.min(300, window.innerWidth - 24);
  menu.style.width = `${width}px`;
  if (rect.top > window.innerHeight / 2) {
    menu.style.top = '';
    menu.style.bottom = `${window.innerHeight - rect.top + 8}px`;
    menu.style.left = `${Math.max(12, rect.left)}px`;
  } else {
    menu.style.bottom = '';
    menu.style.top = `${rect.bottom + 8}px`;
    menu.style.left = `${Math.max(12, Math.min(rect.right - width, window.innerWidth - width - 12))}px`;
  }
  setTimeout(() => document.addEventListener('click', outsideMenuClick), 0);
}

function closeProfileMenu() {
  document.getElementById('profile-menu').hidden = true;
  document.removeEventListener('click', outsideMenuClick);
}

function outsideMenuClick(e) {
  if (!e.target.closest('#profile-menu')) closeProfileMenu();
}

function renderProfileMenu() {
  const menu = document.getElementById('profile-menu');
  const items = profilesList.length ? profilesList : [{ id: 'default', name: 'Hassaan Nasir', title: 'Senior Full Stack & AI Engineer', initials: 'HN', complete: true }];
  menu.innerHTML = `
    <div class="pm-label">Switch profile</div>
    ${profilesLoadFailed ? '<div class="pm-error">Couldn’t load the other profiles from the server. If this is the live site, check that the app is deployed from the <code>web</code> folder.</div>' : ''}
    ${items.map(p => `
      <button class="pm-item ${p.id === activeProfile ? 'active' : ''}" onclick="switchProfile('${p.id}')" role="menuitemradio" aria-checked="${p.id === activeProfile}">
        <span class="avatar pm-avatar">${escapeHtml(p.initials)}</span>
        <span class="pm-text">
          <strong>${escapeHtml(p.name || p.label)}</strong>
          <small>${escapeHtml(p.title)}</small>
        </span>
        ${p.complete ? '' : '<span class="pm-badge">Empty</span>'}
        ${p.id === activeProfile ? '<svg class="pm-check" viewBox="0 0 24 24"><path d="M5 13l4 4L19 7"/></svg>' : ''}
      </button>`).join('')}
    <div class="pm-divider"></div>
    <button class="pm-action" onclick="closeProfileMenu(); openProfile()">
      <svg viewBox="0 0 24 24"><circle cx="12" cy="8" r="4"/><path d="M4 21a8 8 0 0 1 16 0"/></svg>View profile
    </button>
    <button class="pm-action" onclick="closeProfileMenu(); openProfileEditor()">
      <svg viewBox="0 0 24 24"><path d="M4 20h4L19 9l-4-4L4 16z"/><path d="M13.5 6.5l4 4"/></svg>Edit profile
    </button>
    <button class="pm-action" onclick="chooseCvFile()">
      <svg viewBox="0 0 24 24"><path d="M12 15V3M7 8l5-5 5 5M4 21h16"/></svg>Import from CV
    </button>`;
}

// ---------- Switching ----------

async function switchProfile(id) {
  closeProfileMenu();
  if (id === activeProfile) return;
  activeProfile = id;
  try { localStorage.setItem('activeProfile', id); } catch (e) {}

  profileData = null;
  applications = [];
  applyProfileIdentity();
  resetEvaluator();
  resetTailor();
  cveProfileChanged();

  await loadTrackerData();
  renderKanban();
  renderDashboard();

  const p = currentProfile();
  document.getElementById('search-query-input').value = p && !p.original ? p.title : 'Senior Full Stack Engineer';
  if (document.getElementById('tab-search').classList.contains('active')) executeJobSearch();

  showToast(`Switched to ${p ? (p.name || p.label) : 'profile'}${p && !p.complete ? ' — this profile is still empty' : ''}`);
}

function resetEvaluator() {
  const ring = document.getElementById('eval-score-ring');
  ring.style.setProperty('--score', 0);
  ring.classList.remove('good', 'fair', 'low');
  document.getElementById('eval-overall-score').textContent = '–';
  document.getElementById('eval-verdict-text').textContent = 'No evaluation yet';
  ['tech', 'exp', 'beh', 'car'].forEach(id => {
    document.getElementById(`bar-${id}`).style.width = '0%';
    document.getElementById(`val-${id}`).textContent = '–';
  });
  document.getElementById('bar-loc').style.width = '0%';
  document.getElementById('val-loc').textContent = '–';
  document.getElementById('eval-strengths-list').innerHTML = '<li class="muted-li">Paste a job and click Calculate fit score.</li>';
}

function resetTailor() {
  tailorResult = null;
  tailorWs.cv = null;
  tailorWs.result = null;
  tailorWs.edited = false;
  document.getElementById('tailor-edit-card').hidden = true;
  document.getElementById('tailor-style-bar').hidden = true;
  document.getElementById('tailor-analysis').hidden = true;
  document.getElementById('tailor-preview').hidden = true;
  document.getElementById('tailor-empty').hidden = false;
}

// ---------- Editor ----------

// `draft` is profile markdown to review before saving (e.g. read from an uploaded CV)
async function openProfileEditor(draft = null, noticeHtml = '') {
  await openProfile();
  const p = profileData || {};
  const current = currentProfile();
  document.getElementById('profile-body').innerHTML = `
    <div class="editor">
      <div class="editor-head">
        <h2 class="editor-title">${draft ? 'Review imported profile' : 'Edit profile'}</h2>
        <button class="btn btn-secondary editor-upload" onclick="chooseCvFile()">
          <svg viewBox="0 0 24 24"><path d="M12 15V3M7 8l5-5 5 5M4 21h16"/></svg>
          <span>Upload CV</span>
        </button>
      </div>
      ${noticeHtml}
      <p class="muted editor-help">
        ${current && current.builtin
          ? 'This is the main profile that <code>/apply</code> and the other Claude Code commands also use.'
          : 'Fill in each section. Lines inside <code>&lt;!-- --&gt;</code> are examples and are ignored.'}
        Keep the headings and the <code>- **Label:**</code> format so the dashboard can read it.
      </p>
      <textarea id="profile-editor" class="input editor-area" spellcheck="false">${escapeHtml(draft ?? p.rawMarkdown ?? '')}</textarea>
      <div class="editor-actions">
        <button class="btn btn-secondary" onclick="cancelProfileEditor()">Cancel</button>
        <button class="btn btn-primary" id="profile-save" onclick="saveProfileEditor()">Save profile</button>
      </div>
    </div>`;
  document.getElementById('profile-editor').focus();
}

function cancelProfileEditor() {
  renderProfile(profileData || {});
}

async function saveProfileEditor() {
  const markdown = document.getElementById('profile-editor').value;
  const button = document.getElementById('profile-save');
  button.disabled = true;
  try {
    const res = await fetch(apiUrl('/api/profile'), {
      method: 'PUT',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ markdown })
    });
    const data = await res.json();
    if (!res.ok) throw new Error(data.error || 'Save failed');

    const [profileRes, listRes] = await Promise.all([fetch(apiUrl('/api/profile')), fetch('/api/profiles')]);
    profileData = await profileRes.json();
    profilesList = await listRes.json();
    applyProfileIdentity();
    renderProfile(profileData);
    showToast('Profile saved');
  } catch (err) {
    showToast(err.message || 'Save failed');
    button.disabled = false;
  }
}


// CV import: read an uploaded CV (PDF, Word .docx, or text) in the browser and
// draft a profile from it. The draft opens in the profile editor so it can be
// checked and adjusted before saving; nothing is saved automatically.
// Relies on app.js / profiles-ui.js helpers (showToast, escapeHtml, openProfileEditor, profileData).

const CV_LIBS = {
  pdf: 'https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.min.js',
  pdfWorker: 'https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js',
  docx: 'https://cdnjs.cloudflare.com/ajax/libs/mammoth/1.8.0/mammoth.browser.min.js'
};
const CV_MAX_BYTES = 10 * 1024 * 1024;

const loadedScripts = {};
function loadScript(src) {
  if (!loadedScripts[src]) {
    loadedScripts[src] = new Promise((resolve, reject) => {
      const s = document.createElement('script');
      s.src = src;
      const fail = () => { delete loadedScripts[src]; s.remove(); reject(new Error('Could not load the CV reader. Check your internet connection and try again.')); };
      const timer = setTimeout(fail, 30000);
      s.onload = () => { clearTimeout(timer); resolve(); };
      s.onerror = () => { clearTimeout(timer); fail(); };
      document.head.appendChild(s);
    });
  }
  return loadedScripts[src];
}

// ---------- Entry points ----------

function chooseCvFile() {
  closeProfileMenu();
  const input = document.getElementById('cv-file');
  input.value = '';
  input.click();
}

async function handleCvFile(input) {
  const file = input.files && input.files[0];
  if (!file) return;
  if (file.size > CV_MAX_BYTES) {
    showToast('That file is larger than 10 MB');
    return;
  }

  const current = typeof currentProfile === 'function' ? currentProfile() : null;
  if (current && current.complete && !confirm(
    `Replace ${current.name || current.label}'s profile with the details from "${file.name}"?\n\n` +
    'You can review the result before anything is saved.' +
    (current.builtin ? '\n\nThis is the main profile that /apply also uses.' : ''))) {
    return;
  }

  // Stays visible until reading finishes (PDF/Word readers load on first use)
  showToast(`Reading ${file.name}…`, 60000);
  try {
    const cv = await readCv(file);
    await openProfileEditor(buildProfileMarkdown(cv, profileData && profileData.rawMarkdown), importSummary(cv, file.name));
    showToast('CV read. Review the details, then click Save profile.', 4000);
  } catch (err) {
    console.warn('CV import failed', err);
    showToast(friendlyCvError(err), 8000);
  }
}

function friendlyCvError(err) {
  const name = (err && err.name) || '';
  const msg = (err && err.message) || '';
  if (name === 'PasswordException' || /password/i.test(msg)) {
    return 'This PDF is password-protected. Save a copy without the password, then upload that.';
  }
  if (name === 'InvalidPDFException' || /invalid pdf|pdf structure|missing pdf/i.test(msg)) {
    return 'This PDF looks damaged or isn\'t a real PDF. Try exporting it again, or upload the Word version.';
  }
  if (/end of central directory|corrupted zip|could not find file|can't find end/i.test(msg)) {
    return 'This Word file couldn\'t be opened. Save it again as .docx (or PDF) and retry.';
  }
  return msg || 'Could not read this CV';
}

// Parse every text reconstruction of the file and keep the one that reads best
async function readCv(file) {
  const candidates = await extractCvCandidates(file);
  let best = null;
  for (const text of candidates) {
    if (text.replace(/\s/g, '').length < 80) continue;
    let cv;
    try { cv = parseCvText(text); } catch (e) { console.warn('CV parse attempt failed', e); continue; }
    const score = cvScore(cv);
    if (!best || score > best.score) best = { cv, score };
  }
  if (!best) throw new Error('No readable text found in this file. If it is a scanned PDF, upload a Word or text version instead.');
  return best.cv;
}

function cvScore(cv) {
  return (cv.name ? 10 : 0) + cv.experience.length * 8
    + cv.experience.reduce((n, j) => n + Math.min(j.bullets.length, 12) + (j.company !== 'Company' ? 2 : 0), 0)
    + cv.education.length * 4 + cv.projects.length * 2 + cv.languages.length + cv.certifications.length
    + Math.min(cv.skills.reduce((n, g) => n + g.items.length, 0), 40) * 0.25 + (cv.summary ? 3 : 0);
}

// ---------- Text extraction ----------

// All plausible text versions of the file (PDFs with two columns can be read
// row by row or column by column; the parser decides which reads better)
async function extractCvCandidates(file) {
  const name = file.name.toLowerCase();
  if (name.endsWith('.pdf') || file.type === 'application/pdf') {
    const { merged, split } = await extractPdfVariants(file);
    return split ? [merged, split] : [merged];
  }
  return [await extractCvText(file)];
}

async function extractCvText(file) {
  const name = file.name.toLowerCase();
  if (name.endsWith('.pdf') || file.type === 'application/pdf') return (await extractPdfVariants(file)).merged;
  if (name.endsWith('.docx')) return extractDocxText(file);
  if (name.endsWith('.doc')) throw new Error('Old .doc files aren\'t supported. Save it as .docx or PDF and try again.');
  if (/\.(txt|md|markdown|text)$/.test(name) || file.type.startsWith('text/')) return file.text();
  throw new Error('Please upload a PDF, Word (.docx) or text file.');
}

async function extractPdfVariants(file) {
  await loadScript(CV_LIBS.pdf);
  const pdfjs = window.pdfjsLib;
  pdfjs.GlobalWorkerOptions.workerSrc = CV_LIBS.pdfWorker;
  const doc = await pdfjs.getDocument({ data: await file.arrayBuffer() }).promise;
  const pages = [];
  const links = new Set();
  for (let n = 1; n <= doc.numPages; n++) {
    const page = await doc.getPage(n);
    pages.push(pdfItemsToLines((await page.getTextContent()).items));
    for (const a of await page.getAnnotations()) {
      if (a.url && /linkedin\.com|github\.com/i.test(a.url)) links.add(a.url);
    }
  }
  const running = runningLines(pages.map(p => p.merged));
  const clean = lines => lines.filter(l => !running.has(l.trim()) && !/^(page\s*)?\d{1,3}\s*(\/|of)\s*\d{1,3}$/i.test(l.trim()) && !/^page\s*\d{1,3}$/i.test(l.trim()));
  const tail = links.size ? `\n${[...links].join('\n')}` : '';
  const merged = pages.map(p => clean(p.merged).join('\n')).join('\n') + tail;
  const split = pages.some(p => p.split) ? pages.map(p => clean(p.split || p.merged).join('\n')).join('\n') + tail : null;
  return { merged, split };
}

// Lines repeated at the top or bottom of several pages (running headers/footers)
function runningLines(pageLines) {
  const seen = new Map();
  if (pageLines.length < 2) return new Set();
  for (const lines of pageLines) {
    const edge = new Set([...lines.slice(0, 2), ...lines.slice(-2)].map(l => l.trim().replace(/\d+/g, '#')).filter(Boolean));
    for (const l of edge) seen.set(l, (seen.get(l) || 0) + 1);
  }
  const repeated = new Set([...seen].filter(([, n]) => n >= 2).map(([l]) => l));
  const out = new Set();
  for (const lines of pageLines) for (const l of lines) if (repeated.has(l.trim().replace(/\d+/g, '#'))) out.add(l.trim());
  return out;
}

// Rebuild reading-order lines from positioned PDF text. Large horizontal gaps
// (separate columns, e.g. dates beside a job title) become triple spaces.
// Returns the page read row by row ("merged") and, when a second column is found,
// column by column ("split": the fuller column first, then the other)
function pdfItemsToLines(items) {
  const rows = [];
  const colX = detectColumn(items);
  for (const it of items) {
    if (!it.str || !it.str.trim()) continue;
    const y = it.transform[5];
    const size = Math.abs(it.transform[0]) || 10;
    let row = rows.find(r => Math.abs(r.y - y) < size * 0.5);
    if (!row) rows.push(row = { y, size, items: [] });
    row.items.push({ x: it.transform[4], w: it.width, s: it.str });
  }
  rows.sort((a, b) => b.y - a.y);
  const joinRow = (r, list) => {
    let line = '';
    let end = null;
    for (const it of list) {
      if (end !== null) {
        const gap = it.x - end;
        // Text starting at the page's second column (e.g. job details beside dates)
        const atColumn = colX !== null && Math.abs(it.x - colX) <= 3 && gap > 1;
        if (gap > r.size * 2 || atColumn) line += '   ';
        else if (gap > r.size * 0.15 && !line.endsWith(' ') && !it.s.startsWith(' ')) line += ' ';
      }
      line += it.s;
      end = it.x + it.w;
    }
    return line.trim();
  };
  const merged = rows.map(r => { r.items.sort((a, b) => a.x - b.x); return joinRow(r, r.items); }).filter(Boolean);
  if (colX === null) return { merged, split: null };
  const left = [], right = [];
  for (const r of rows) {
    const l = joinRow(r, r.items.filter(it => it.x < colX - 3));
    const rt = joinRow(r, r.items.filter(it => it.x >= colX - 3));
    if (l) left.push(l);
    if (rt) right.push(rt);
  }
  const chars = a => a.join('').length;
  const split = chars(left) >= chars(right) ? [...left, ...right] : [...right, ...left];
  return { merged, split };
}

// Many CV templates have a narrow left column (dates, labels, project names) and a
// wide right column. Find the x position where the right column starts: the place
// most often reached by a line's second piece of text.
function detectColumn(items) {
  // Rows of text (same baseline), each with its item x positions sorted
  const rows = [];
  for (const it of items) {
    if (!it.str || !it.str.trim()) continue;
    const y = it.transform[5];
    const size = Math.abs(it.transform[0]) || 10;
    let row = rows.find(r => Math.abs(r.y - y) < size * 0.5);
    if (!row) rows.push(row = { y, xs: [] });
    row.xs.push(Math.round(it.transform[4]));
  }
  if (rows.length < 6) return null;
  const minX = Math.min(...rows.map(r => Math.min(...r.xs)));
  // Candidate column starts: text that begins a new column within a row, or a row
  // that starts well to the right of the page margin (a sidebar or second column)
  const counts = new Map();
  const add = x => { const k = Math.round(x / 2) * 2; counts.set(k, (counts.get(k) || 0) + 1); };
  for (const r of rows) {
    r.xs.sort((a, b) => a - b);
    for (const x of new Set(r.xs.slice(1))) if (x > minX + 30) add(x);
    if (r.xs[0] > minX + 30) add(r.xs[0]);
  }
  // Merge neighbouring positions (±3pt) and pick the strongest
  let best = null;
  for (const [x] of counts) {
    let n = 0;
    for (const [x2, c] of counts) if (Math.abs(x2 - x) <= 3) n += c;
    if (n >= 4 && (!best || n > best.n)) best = { x, n };
  }
  return best ? best.x : null;
}

async function extractDocxText(file) {
  await loadScript(CV_LIBS.docx);
  const result = await window.mammoth.extractRawText({ arrayBuffer: await file.arrayBuffer() });
  return result.value;
}

// ---------- Parsing ----------

const CV_SECTIONS = [
  ['summary', /^(professional |career |personal )?(summary|profile|about( me)?|objective|overview|statement)$/],
  ['experience', /^((professional|work|relevant|employment|career) )?(experience|history|employment( history)?)$|^work history$|^employment$/],
  ['education', /^(education|academic (background|qualifications)|qualifications|education (and|&) training)$/],
  ['skills', /^((technical|core|key|professional) )?(skills|competencies|expertise|technologies|tech stack|tools)( (and|&) (tools|technologies|expertise))?$|^skills (and|&) (tools|technologies|expertise)$/],
  ['projects', /^((key|selected|personal|independent|academic|notable|featured|side|recent|major|relevant|open[- ]source|professional) )?projects( (and|&) \w+)?$|^portfolio$/],
  ['certifications', /^(certifications?|certificates|licenses?( (and|&) certifications)?|courses( (and|&) certifications)?|training)$/],
  ['languages', /^languages?( skills)?$/],
  ['ignore', /^(awards?|honou?rs|interests|hobbies|references|publications|volunteer(ing| experience)?|achievements|activities|extracurricular.*)$/]
];

const MONTH = '(?:jan|feb|mar|apr|may|jun|jul|aug|sep|sept|oct|nov|dec)[a-z]*\\.?';
const CV_DATE = `(?:${MONTH}\\s*,?\\s*)?(?:19|20)\\d{2}|\\d{1,2}[/.](?:19|20)\\d{2}|${MONTH}\\s*['’]\\s*\\d{2}`;
const SINCE_RE = new RegExp(`\\b(?:since|from)\\s+((?:${MONTH}\\s*)?(?:19|20)\\d{2})`, 'i');
const DURATION_RE = /\(?\s*\d+\s*(?:yrs?|years?)(?:\s*\d+\s*(?:mos?|months?))?\s*\)?|\(?\s*\d+\s*(?:mos?|months?)\s*\)?/gi;
const RANGE_RE = new RegExp(`(${CV_DATE})\\s*(?:–|—|-|to|until)+\\s*(${CV_DATE}|present|current|now|today|ongoing)`, 'i');
const YEAR_RE = /(?:19|20)\d{2}/g;

const ROLE_WORDS = /\b(engineer|developer|designer|manager|analyst|lead|architect|consultant|scientist|intern|specialist|director|officer|administrator|devops|sre|head|founder|co-founder|coordinator|associate|executive|programmer|researcher|technician|product owner|owner|assistant|trainee|freelancer|contractor|tester|qa)\b/i;
const PLACE_WORDS = /\b(remote|hybrid|on-?site|pakistan|uae|united arab emirates|dubai|abu dhabi|india|usa|united states|uk|united kingdom|england|germany|canada|australia|singapore|saudi arabia|ksa|qatar|egypt|netherlands|france|spain|italy|ireland|sweden|poland|turkey|türkiye|china|japan|nigeria|kenya|south africa|bangladesh|sri lanka|malaysia|indonesia|philippines|new zealand|switzerland|austria|belgium|denmark|norway|finland|portugal|brazil|mexico|lahore|karachi|islamabad|london|berlin|new york|toronto|sydney|bangalore|bengaluru|mumbai|delhi|hyderabad|riyadh|doha|cairo)\b/i;
const EDU_WORDS = /\b(bachelor'?s?|master'?s?|b\.?\s?sc|m\.?\s?sc|bsc|msc|b\.?s\.?|m\.?s\.?|b\.?a\.?|m\.?a\.?|mba|ph\.?\s?d|doctorate|diploma|associate degree|b\.?\s?tech|m\.?\s?tech|b\.?\s?e\.?|beng|meng|bcs|bscs|mcs|a-?levels?|o-?levels?|intermediate|matric(ulation)?|hssc|ssc|high school|fsc|ics)\b/i;
const SCHOOL_WORDS = /\b(universit(?:y|ies)|colleges?|institutes?|schools?|academ(?:y|ies)|polytechnic|nuces|fast|lums|nust|comsats|iit|mit)\b/i;

const BULLET_RE = /^\s*(?:[\p{So}\p{Co}\p{Cc}•●▪■◦‣∙·➢➤►▶✓✔]\s*|[*\-–—]\s+|\d+[.)]\s+)/u;

// Lines that read like an achievement rather than a job title / company
const ACTION_START = /^(rebuilt|redesigned|reworked|revamped|grew|expanded|lowered|raised|boosted|accelerated|enabled|defined|drafted|facilitated|negotiated|presented|published|secured|simplified|standardi[sz]ed|transformed|unified|upgraded|validated|taught|rolled out|won|cut|built|led|leading|designed|developed|created|implemented|managed|wrote|written|cut|reduced|improved|increased|modell?ed|mentored|delivered|launched|owned|drove|introduced|migrated|automated|optimi[sz]ed|architected|maintained|collaborated|worked|responsible|supported|established|spearheaded|streamlined|engineered|analy[sz]ed|coordinated|conducted|achieved|integrated|deployed|shipped|scaled|partnered|researched|tested|trained|oversaw|handled|prepared|produced|planned|organi[sz]ed|contributed|assisted|helped|ran|set up|refactored)\b/i;

function cleanLine(l) {
  return l.replace(/ /g, ' ').replace(/[​﻿]/g, '').replace(/[ \t]+$/g, '');
}

// Headings compared with spaces and punctuation removed, so letter-spaced
// headings like "E XP ER I EN C E" or "S K IL LS" are recognised too
const CV_HEADINGS = {
  summary: ['summary', 'profile', 'professionalsummary', 'careersummary', 'professionalprofile', 'aboutme', 'about', 'objective', 'careerobjective', 'overview', 'personalstatement'],
  experience: ['experience', 'workexperience', 'professionalexperience', 'relevantexperience', 'employmenthistory', 'employment', 'workhistory', 'careerhistory'],
  education: ['education', 'academicbackground', 'academicqualifications', 'qualifications', 'educationandtraining'],
  contact: ['contact', 'contactinfo', 'contactinformation', 'contactdetails', 'personaldetails', 'personalinformation', 'personalinfo'],
  skills: ['skills', 'topskills', 'technicalskills', 'coreskills', 'keyskills', 'corecompetencies', 'competencies', 'expertise', 'technologies', 'techstack', 'skillsandtools', 'skillsandtechnologies', 'toolsandtechnologies', 'tools'],
  projects: ['projects', 'keyprojects', 'selectedprojects', 'personalprojects', 'featuredprojects', 'sideprojects', 'independentprojects', 'academicprojects', 'notableprojects', 'portfolio'],
  certifications: ['certifications', 'certification', 'certificates', 'licenses', 'licensesandcertifications', 'coursesandcertifications', 'courses', 'training'],
  languages: ['languages', 'language', 'languageskills'],
  ignore: ['awards', 'honors', 'honours', 'awardsandhonors', 'interests', 'hobbies', 'references', 'publications', 'volunteering', 'volunteerexperience', 'achievements', 'activities']
};

function sectionOf(line) {
  const t = line.trim().replace(/[:：]$/, '').replace(/\s+/g, ' ').toLowerCase();
  if (!t || t.length > 45) return null;
  const letterSpaced = /^[a-z&]+( +[a-z&]+)+$/.test(t) && t.split(' ').filter(w => w.length <= 2).length >= 2;
  if (!letterSpaced && t.split(' ').length > 5) return null;
  for (const [name, re] of CV_SECTIONS) if (re.test(t)) return name;
  const squashed = t.replace(/&/g, 'and').replace(/[^a-z]/g, '');
  for (const [name, list] of Object.entries(CV_HEADINGS)) if (list.includes(squashed)) return name;
  return null;
}

// In two-column layouts a date range often wraps: "Feb 2026 –" on one line and
// "Present" (or "2026") at the start of the next. Put the range back together.
function joinSplitRanges(lines) {
  const startRe = new RegExp(`^(.*?)(${CV_DATE})\\s*[–—-]\\s*(${MONTH})?\\s*?((?:\\s{3,}|\\s+(?=[A-Z])).*)?$`, 'i');
  const endRe = /^\s*((?:19|20)\d{2}|present|current|now|today|ongoing)\b(\s*\(expected\))?\s*(.*)$/i;
  for (let i = 0; i < lines.length - 1; i++) {
    const a = lines[i].match(startRe);
    if (!a || RANGE_RE.test(lines[i])) continue;
    const b = lines[i + 1].match(endRe);
    if (!b) continue;
    lines[i] = `${a[1]}${a[2]} – ${a[3] ? a[3] + ' ' : ''}${b[1]}${a[4] ? a[4] : ''}`;
    lines[i + 1] = b[3] ? `   ${b[3]}` : '';
  }
  return lines;
}

function parseCvText(raw) {
  const lines = joinSplitRanges(raw.split(/\r?\n/).map(cleanLine));
  const sections = { header: [] };
  let current = 'header';
  for (const line of lines) {
    const name = sectionOf(line);
    if (name) { current = name; sections[current] = sections[current] || []; continue; }
    (sections[current] = sections[current] || []).push(line);
  }

  const all = raw;
  const email = (all.match(/[\w.+-]+@[\w-]+(?:\.[\w-]+)+/) || [])[0] || '';
  const linkedinMatch = all.match(/(?:https?:\/\/)?(?:[a-z]{2,3}\.)?linkedin\.com\/in\/[\w%-]+\/?/i);
  const linkedinShort = all.match(/linkedin\s*:?\s*(?:\/?in\/)([\w%-]{3,})/i);
  const linkedin = linkedinMatch
    ? (linkedinMatch[0].startsWith('http') ? linkedinMatch[0] : `https://${linkedinMatch[0]}`).replace(/\/$/, '')
    : linkedinShort ? `https://linkedin.com/in/${linkedinShort[1]}` : '';
  const githubMatch = all.match(/(?:https?:\/\/)?github\.com\/[\w-]+/i);
  const github = githubMatch ? (githubMatch[0].startsWith('http') ? githubMatch[0] : `https://${githubMatch[0]}`) : '';
  const phone = (all.match(/(?:\+\d{1,3}[\s-]?)?(?:\(?\d{2,4}\)?[\s.-]?){2,4}\d{3,4}/g) || [])
    .map(p => p.trim())
    .find(p => p.replace(/\D/g, '').length >= 9 && !RANGE_RE.test(p)) || '';

  const header = parseHeader(sections.header.filter(l => l.trim()), { email, phone });
  // Sidebar "Contact" blocks often hold the location
  if (!header.location && sections.contact) {
    const place = sections.contact.flatMap(l => splitSegments(l.trim())).find(seg => PLACE_WORDS.test(seg) && !/@|https?:|www\./i.test(seg) && seg.length <= 60);
    if (place) header.location = place;
  }

  return {
    ...header,
    email,
    phone,
    linkedin,
    github,
    summary: (sections.summary || []).map(l => l.trim()).filter(Boolean).join(' ').replace(BULLET_RE, ''),
    experience: parseExperience(sections.experience || []),
    education: parseEducation(sections.education || []),
    skills: parseSkills(sections.skills || []),
    projects: parseProjects(sections.projects || []),
    certifications: (sections.certifications || []).map(l => l.replace(BULLET_RE, '').trim()).filter(l => l.length > 2),
    languages: parseLanguages(sections.languages || [])
  };
}

function isContactish(s, contact) {
  return /@|https?:|www\.|linkedin|github|\d{6,}/i.test(s) || (contact.phone && s.includes(contact.phone));
}

function splitSegments(line) {
  return line.split(/\s*[|•·●▪]\s*|\s{3,}|\s+[—–]\s+|\s+-\s+/)
    // Icon-font glyphs (phone, mail, GitHub icons) come through as stray symbols
    .map(s => s.replace(/^[^\p{L}\p{N}+(]+/u, '').replace(/[\p{Co}]/gu, '').trim())
    .filter(Boolean);
}

// "HuzaifaArif" (letter-spaced PDF text) -> "Huzaifa Arif"
function unsquashName(seg) {
  return /^[A-Z][a-z]+(?:[A-Z][a-z]+){1,3}$/.test(seg) ? seg.replace(/([a-z])([A-Z])/g, '$1 $2') : seg;
}

function parseHeader(lines, contact) {
  let name = '';
  let title = '';
  let location = '';
  const segments = lines.slice(0, 10).flatMap(l => splitSegments(l.trim()));

  for (const rawSeg of segments) {
    if (isContactish(rawSeg, contact)) continue;
    const seg = unsquashName(rawSeg);
    if (!name && /^[A-Za-zÀ-ÿ.'’-]+(?:\s+[A-Za-zÀ-ÿ.'’-]+){1,3}$/.test(seg) && !ROLE_WORDS.test(seg) && !PLACE_WORDS.test(seg) && /[A-Z]/.test(seg[0])) {
      name = seg.split(/\s+/).map(w => (w === w.toUpperCase() && w.length > 2 ? w[0] + w.slice(1).toLowerCase() : w)).join(' ');
      continue;
    }
    if (name && !title && seg.split(/\s+/).length <= 10 && (ROLE_WORDS.test(seg) || /&/.test(seg)) && !PLACE_WORDS.test(seg)) {
      title = seg;
      continue;
    }
    if (!location && PLACE_WORDS.test(seg) && seg.length <= 80 && !ROLE_WORDS.test(seg)) {
      location = seg.replace(/^(address|location)\s*:\s*/i, '');
    }
  }
  return { name, title, location };
}

function normalisePeriod(match) {
  const year = s => {
    const full = s.match(/(?:19|20)\d{2}/);
    if (full) return full[0];
    const short = s.match(/['’]\s*(\d{2})/);
    if (!short) return '';
    const yy = Number(short[1]);
    return String(yy <= (new Date().getFullYear() % 100) + 1 ? 2000 + yy : 1900 + yy);
  };
  const end = /present|current|now|today|ongoing/i.test(match[2]) ? 'Present' : year(match[2]);
  return `${year(match[1])} – ${end}`;
}

function parseExperience(lines) {
  const jobs = [];
  let job = null;
  let pendingHeader = [];

  const startJob = (headerParts, period) => {
    job = { headerParts, period, bullets: [], extraHeader: 0, marked: 0, unmarkedBeforeMarked: 0 };
    jobs.push(job);
  };

  // A bullet that doesn't end a sentence continues on the next line, whatever its case
  const continues = (last, line) => last && !/[.!?]$/.test(last) && !ACTION_START.test(line);

  for (const rawLine of lines) {
    const line = rawLine.trim();
    // Skip empty lines and stray bullet symbols on their own line
    if (!line || !line.replace(BULLET_RE, '').trim()) continue;
    let range = line.match(RANGE_RE);
    const since = !range && line.match(SINCE_RE);
    if (since) range = Object.assign([since[0], since[1], 'Present'], { index: since.index });
    const isBullet = BULLET_RE.test(line);

    if (range && !isBullet) {
      const rest = line.replace(range[0], ' ').replace(DURATION_RE, ' ').replace(/[()]/g, ' ').replace(/\(?expected\)?/i, ' ').replace(/\s{2,}/g, '   ').trim();
      const parts = [...pendingHeader];
      if (rest) parts.push(rest);
      startJob(parts, normalisePeriod(range));
      pendingHeader = [];
      continue;
    }

    if (isBullet) {
      if (job) {
        if (!job.marked) job.unmarkedBeforeMarked = job.bullets.length;
        job.marked++;
        job.bullets.push(line.replace(BULLET_RE, '').trim());
      }
      pendingHeader = [];
      continue;
    }

    const words = line.split(/\s+/).length;
    const looksLikeAchievement = ACTION_START.test(line) || /[.!]$/.test(line) || /\d+\s*%/.test(line);
    const last = job ? job.bullets[job.bullets.length - 1] : null;
    if (job && continues(last, line) && !range) {
      job.bullets[job.bullets.length - 1] = `${last} ${line}`;
    } else if (job && looksLikeAchievement) {
      job.bullets.push(line);
    } else if (job && job.bullets.length === 0 && job.extraHeader < 2 && words <= 12) {
      // Company / location line right under a dated job title
      job.headerParts.push(line);
      job.extraHeader++;
    } else if (job && words > 12) {
      job.bullets.push(line);
    } else {
      pendingHeader.push(line);
      if (pendingHeader.length > 3) pendingHeader.shift();
    }
  }

  // When a job uses bullet markers, the unmarked lines above the first marker are
  // a company description (e.g. an italic "About the company" line), not achievements
  for (const j of jobs) {
    if (j.marked && j.unmarkedBeforeMarked) j.bullets = j.bullets.slice(j.unmarkedBeforeMarked);
  }

  return jobs.map(j => {
    const pieces = j.headerParts
      .flatMap(p => p.split(/\s*(?:\||·|•|—|–|\s-\s|\s@\s|,\s|\s{3,})\s*|\s+at\s+/i))
      .map(s => s.trim().replace(/^[,;:]+|[,;:]+$/g, ''))
      .filter(Boolean);
    const role = pieces.find(p => ROLE_WORDS.test(p)) || pieces[0] || 'Role';
    const locationParts = pieces.filter(p => p !== role && PLACE_WORDS.test(p));
    const company = pieces.find(p => p !== role && !locationParts.includes(p)) || 'Company';
    return {
      role: role.replace(/\s+-\s+/g, ' – '),
      company: company.replace(/\s+-\s+/g, ' – '),
      location: locationParts.join(', '),
      period: j.period,
      bullets: j.bullets.filter(b => b.length > 3)
    };
  });
}

function parseEducation(lines) {
  const entries = [];
  let entry = null;
  for (const rawLine of lines) {
    const line = rawLine.replace(BULLET_RE, '').trim();
    if (!line) continue;
    const years = line.match(YEAR_RE) || [];
    const schoolPart = () => (splitSegments(line).find(p => SCHOOL_WORDS.test(p)) || line)
      .replace(RANGE_RE, '').replace(YEAR_RE, '').replace(/[|,–-]+\s*$/, '').trim();
    if (EDU_WORDS.test(line)) {
      const pieces = line.split(/\s*(?:\||·|•|—|–|\s-\s|,\s|\.\s(?=[A-Z])|\s{3,})\s*/).map(s => s.trim()).filter(Boolean);
      // The degree is everything before the institution: "Bachelor of Science, Computer Science"
      const schoolAt = pieces.findIndex(p => SCHOOL_WORDS.test(p) && !EDU_WORDS.test(p));
      const degreeStart = pieces.findIndex(p => EDU_WORDS.test(p));
      const degreeParts = pieces.slice(degreeStart, schoolAt > degreeStart ? schoolAt : degreeStart + 1)
        .filter(p => !PLACE_WORDS.test(p) && !RANGE_RE.test(p) && !/^\(?(?:19|20)\d{2}/.test(p));
      const degree = (degreeParts.join(', ') || line).replace(RANGE_RE, '').replace(YEAR_RE, '').replace(/[()]/g, '').replace(/[.,]\s*$/, '').trim();
      const school = pieces.find(p => SCHOOL_WORDS.test(p) && !EDU_WORDS.test(p)) || '';
      if (entry && !entry.degree) {
        entry.degree = degree;
        entry.school = entry.school || school;
        entry.years.push(...years);
      } else {
        entry = { degree, school, years: [...years] };
        entries.push(entry);
      }
    } else if (SCHOOL_WORDS.test(line) && (!entry || entry.school)) {
      entry = { degree: '', school: schoolPart(), years: [...years] };
      entries.push(entry);
    } else if (entry) {
      if (!entry.school && SCHOOL_WORDS.test(line)) entry.school = schoolPart();
      entry.years.push(...years);
    }
  }
  return entries.map(e => ({
    degree: e.degree || 'Degree',
    school: e.school,
    period: e.years.length > 1 ? `${e.years[0]} - ${e.years[e.years.length - 1]}` : (e.years[0] || '')
  }));
}

function parseSkills(lines) {
  const groups = [];
  const loose = [];
  let lastGroup = null;
  const nextText = i => { for (let k = i + 1; k < lines.length; k++) if (lines[k].trim()) return lines[k]; return ''; };
  for (let i = 0; i < lines.length; i++) {
    const rawLine = lines[i];
    const line = rawLine.replace(BULLET_RE, '').trim();
    if (!line) { lastGroup = null; continue; }
    // A short heading on its own line ("Cloud & DevOps") followed by a comma list
    if (!/[,;:]/.test(line) && line.split(/\s+/).length <= 6 && !/[.]$/.test(line) && /[,;]/.test(nextText(i))) {
      lastGroup = { label: line.replace(/\*\*/g, ''), items: [] };
      groups.push(lastGroup);
      continue;
    }
    const labelled = line.match(/^([^:]{2,40}):\s*(.+)$/)
      || line.match(/^([^,:]{2,30}?)\s{3,}(.+[,;].+)$/)
      || line.match(/^((?:programming )?languages|concepts|technologies|frameworks|libraries|databases|data tools|tools|cloud|devops|platforms|frontend|backend|testing|soft skills|methodologies|other)\s+(.+[,;].+)$/i);
    const split = s => s.split(/\s*(?:,|;|\||•|·|●|▪|\s{3,})\s*/).map(x => x.replace(/\*\*/g, '').replace(/\.$/, '').trim()).filter(x => x && x.length <= 50);
    if (labelled) {
      lastGroup = { label: labelled[1].replace(/\*\*/g, '').trim(), items: split(labelled[2]) };
      groups.push(lastGroup);
    } else if (lastGroup && !BULLET_RE.test(rawLine)) {
      // A wrapped continuation of the previous group's list
      lastGroup.items.push(...split(line));
    } else {
      loose.push(...split(line));
    }
  }
  if (loose.length) groups.push({ label: groups.length ? 'Other' : 'Skills', items: loose });
  return groups.map(g => ({ ...g, items: [...new Set(g.items)] })).filter(g => g.items.length);
}

function parseProjects(lines) {
  const columned = lines.filter(l => /\S\s{3,}\S/.test(l)).length >= 2;
  if (columned) return parseColumnProjects(lines);
  const projects = [];
  for (const rawLine of lines) {
    const line = rawLine.trim();
    if (!line) continue;
    const text = line.replace(BULLET_RE, '').trim();
    // A wrapped line (starts in lowercase) continues the previous project
    if (projects.length && /^[a-z(]/.test(text) && !BULLET_RE.test(line)) {
      const last = projects[projects.length - 1];
      last.desc = `${last.desc} ${text}`.trim();
      continue;
    }
    const named = text.match(/^([^:–—]{2,60})\s*[:–—]\s+(.+)$/)
      || (/^(.{2,40}?)\.\s+[A-Z]/.test(text) && text.match(/^(.{2,40}?)\.\s+([A-Z].+)$/)?.[1].split(/\s+/).length <= 5
        ? text.match(/^(.{2,40}?)\.\s+([A-Z].+)$/) : null);
    const last = projects[projects.length - 1];
    if (named) projects.push({ name: named[1].trim(), desc: named[2].trim() });
    else if (text.split(/\s+/).length <= 6 && !/[.]$/.test(text)) projects.push({ name: text, desc: '' });
    else if (last) last.desc = `${last.desc} ${text}`.trim();
    else projects.push({ name: text.split(/\s+/).slice(0, 4).join(' '), desc: text });
  }
  return projects;
}

// Name in the left column, description in the right; both may wrap over lines
function parseColumnProjects(lines) {
  const projects = [];
  let current = null;
  for (const rawLine of lines) {
    if (!rawLine.trim()) continue;
    const m = rawLine.match(/^\s*(\S.*?)\s{3,}(.*)$/);
    const left = m ? m[1].replace(BULLET_RE, '').trim() : (rawLine.startsWith('   ') ? '' : null);
    const right = m ? m[2].trim() : rawLine.trim();
    const startsNew = left && (!current || /[.!]$/.test(current.desc));
    if (left === null && !current) { current = { name: right, desc: '' }; projects.push(current); continue; }
    if (startsNew) {
      current = { name: left, desc: right };
      projects.push(current);
    } else if (current) {
      if (left) current.name = `${current.name} ${left}`;
      current.desc = `${current.desc} ${right}`.trim();
    }
  }
  return projects.map(p => ({ name: p.name.replace(/\s+/g, ' ').trim(), desc: p.desc.replace(/\s+/g, ' ').trim() }));
}

function parseLanguages(lines) {
  return lines
    .flatMap(l => l.replace(BULLET_RE, '').split(/\s*(?:,|;|\||•|·)\s*(?![^()]*\))/))
    .map(s => s.trim().replace(/\.+$/, ''))
    .filter(Boolean)
    .map(s => {
      const m = s.match(/^([A-Za-zÀ-ÿ]+(?:\s[A-Za-zÀ-ÿ]+)?)\s*(?:(?:[(:–—-]|\s{2,})\s*([^)]+)\)?)?$/);
      return m ? { name: m[1].trim(), level: (m[2] || '').trim() } : null;
    })
    .filter(Boolean)
    .slice(0, 8);
}

// ---------- Profile markdown ----------

function buildProfileMarkdown(cv, existingMarkdown) {
  const md = (s) => String(s || '').replace(/\|/g, '/').trim();
  const front = (existingMarkdown || '').match(/^---\n[\s\S]*?\n---\n/);
  const out = [];
  out.push(front ? front[0].trimEnd() : '---\nprofile_label: Imported from CV\n---');
  out.push('', '# Candidate Profile', '', '<!-- Imported from a CV. Check every section, fix anything that was read wrongly, then click Save profile. -->', '');
  out.push('## Identity');
  out.push(`- **Name:** ${cv.name}`);
  out.push(`- **Title:** ${cv.title}`);
  out.push(`- **Location:** ${cv.location}`);
  if (cv.phone) out.push(`- **Phone:** ${cv.phone}`);
  out.push(`- **Email:** ${cv.email}`);
  out.push(`- **LinkedIn:** ${cv.linkedin}`);
  if (cv.github) out.push(`- **GitHub:** ${cv.github}`);
  out.push('- **Status:**', '');

  out.push('### Languages', '| Language | Level | Notes |', '|----------|-------|-------|');
  cv.languages.forEach(l => out.push(`| ${md(l.name)} | ${md(l.level)} | |`));
  out.push('');

  if (cv.summary) out.push('## Summary', cv.summary, '');

  out.push('## Education', '', '| Degree | Period | Institution | Key Topics |', '|--------|--------|-------------|------------|');
  cv.education.forEach(e => out.push(`| ${md(e.degree)} | ${md(e.period)} | ${md(e.school)} | |`));
  out.push('');

  out.push('## Professional Experience', '');
  cv.experience.forEach(j => {
    out.push(`### ${j.role} - ${j.company} (${j.period})`);
    out.push(j.location || '');
    j.bullets.forEach(b => out.push(`- ${b}`));
    out.push('');
  });
  if (!cv.experience.length) out.push('<!-- No jobs were recognised. Add them like this:\n### Job Title - Company (2022 – 2025)\nCity, Country / Remote\n- What you achieved\n-->', '');

  out.push('## Independent Projects');
  cv.projects.forEach(p => out.push(`- **${p.name}**${p.desc ? `: ${p.desc}` : ''}`));
  out.push('');

  out.push('## Technical Skills', '', '### From CV');
  cv.skills.forEach(g => out.push(`- **${g.label}**: ${g.items.join(', ')}`));
  out.push('');

  out.push('## Certifications');
  cv.certifications.forEach(c => out.push(`- **${c.replace(/\*\*/g, '')}**`));
  out.push('');

  return out.join('\n');
}

function importSummary(cv, fileName) {
  const found = [];
  const missing = [];
  (cv.name ? found : missing).push('name');
  (cv.email ? found : missing).push('email');
  if (cv.experience.length) found.push(`${cv.experience.length} ${cv.experience.length === 1 ? 'job' : 'jobs'} (${cv.experience.reduce((n, j) => n + j.bullets.length, 0)} bullet points)`);
  else missing.push('work experience');
  if (cv.education.length) found.push(`${cv.education.length} education ${cv.education.length === 1 ? 'entry' : 'entries'}`);
  else missing.push('education');
  const skillCount = cv.skills.reduce((n, g) => n + g.items.length, 0);
  if (skillCount) found.push(`${skillCount} skills`);
  else missing.push('skills');
  if (cv.projects.length) found.push(`${cv.projects.length} projects`);
  if (cv.certifications.length) found.push(`${cv.certifications.length} certifications`);

  return `
    <div class="notice ${missing.length ? 'warn' : ''} import-notice">
      <span>
        <strong>Read from ${escapeHtml(fileName)}:</strong> ${escapeHtml(found.join(', ') || 'very little')}.
        ${missing.length ? `<br>Couldn't find: ${escapeHtml(missing.join(', '))}. Add ${missing.length === 1 ? 'it' : 'them'} below.` : ''}
        <br>Check each section and fix anything read wrongly, then click <strong>Save profile</strong>. Nothing is saved until you do.
      </span>
    </div>`;
}


// Boot after every definition above exists
if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', initApp);
} else {
  initApp();
}
